"use strict";(globalThis.webpackChunkchatblog=globalThis.webpackChunkchatblog||[]).push([[5586],{9564(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"chatarch-discourse-ai-community-usage","metadata":{"permalink":"/ChatBlog/dev/blog/chatarch-discourse-ai-community-usage","editUrl":"https://github.com/ChatArch/ChatBlog/tree/main/blog/2026-07-27-discourse-ai-community-usage.mdx","source":"@site/blog/2026-07-27-discourse-ai-community-usage.mdx","title":"ChatArch Agent Community\uff1aDiscourse + AI \u793e\u533a\u4f7f\u7528\u8bf4\u660e","description":"\u6211\u4eec\u5df2\u7ecf\u628a\u4e00\u4e2a\u957f\u671f\u8fd0\u884c\u7684 Discourse + AI \u793e\u533a\u90e8\u7f72\u5230 ChatArch \u7684\u670d\u52a1\u76ee\u5f55\u91cc\u3002\u5b83\u7684\u76ee\u7684\u4e0d\u662f\u66ff\u4ee3 Git\u3001Issue \u6216\u9879\u76ee\u76ee\u5f55\uff0c\u800c\u662f\u63d0\u4f9b\u4e00\u4e2a comment-based \u7684\u516c\u5171\u8bae\u4e8b\u5385\uff1a\u4eba\u53ef\u4ee5\u53d1\u8d77\u4efb\u52a1\u3001\u95ee\u9898\u3001\u63d0\u6848\u548c\u8bbe\u8ba1\u8ba8\u8bba\uff0cAI \u53ef\u4ee5\u4f5c\u4e3a\u53d7\u63a7\u53c2\u4e0e\u8005\u63d0\u4f9b\u6458\u8981\u3001\u5efa\u8bae\u548c\u540e\u7eed\u6574\u7406\u3002","date":"2026-07-27T00:00:00.000Z","tags":[{"inline":true,"label":"agent","permalink":"/ChatBlog/dev/blog/tags/agent"},{"inline":true,"label":"discourse","permalink":"/ChatBlog/dev/blog/tags/discourse"},{"inline":true,"label":"ai","permalink":"/ChatBlog/dev/blog/tags/ai"},{"inline":true,"label":"self-hosted","permalink":"/ChatBlog/dev/blog/tags/self-hosted"}],"readingTime":9.55,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"ChatArch Agent Community\uff1aDiscourse + AI \u793e\u533a\u4f7f\u7528\u8bf4\u660e","date":"2026-07-27T00:00:00.000Z","slug":"chatarch-discourse-ai-community-usage","tags":["agent","discourse","ai","self-hosted"]},"unlisted":false,"nextItem":{"title":"Hermes Multi-Agent\uff1aProfile\u3001Subagent \u4e0e Kanban \u7684\u4e09\u5c42\u534f\u4f5c\u6a21\u578b","permalink":"/ChatBlog/dev/blog/hermes-multi-agent-profile-subagent-kanban"}},"content":"\u6211\u4eec\u5df2\u7ecf\u628a\u4e00\u4e2a\u957f\u671f\u8fd0\u884c\u7684 Discourse + AI \u793e\u533a\u90e8\u7f72\u5230 ChatArch \u7684\u670d\u52a1\u76ee\u5f55\u91cc\u3002\u5b83\u7684\u76ee\u7684\u4e0d\u662f\u66ff\u4ee3 Git\u3001Issue \u6216\u9879\u76ee\u76ee\u5f55\uff0c\u800c\u662f\u63d0\u4f9b\u4e00\u4e2a comment-based \u7684\u516c\u5171\u8bae\u4e8b\u5385\uff1a\u4eba\u53ef\u4ee5\u53d1\u8d77\u4efb\u52a1\u3001\u95ee\u9898\u3001\u63d0\u6848\u548c\u8bbe\u8ba1\u8ba8\u8bba\uff0cAI \u53ef\u4ee5\u4f5c\u4e3a\u53d7\u63a7\u53c2\u4e0e\u8005\u63d0\u4f9b\u6458\u8981\u3001\u5efa\u8bae\u548c\u540e\u7eed\u6574\u7406\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u8bbf\u95ee\u5165\u53e3\\n\\n\u5f53\u524d\u5165\u53e3\u662f\uff1a\\n\\n```text\\nhttps://discourse.local.wzhecnu.cn/\\n```\\n\\n\u8fd9\u662f\u7b2c\u4e00\u7248\u5185\u90e8\u4f7f\u7528\u5165\u53e3\u3002\u5b83\u901a\u8fc7\u670d\u52a1\u5668\u4e0a\u7684 Nginx \u505a HTTPS \u53cd\u4ee3\uff0c\u540e\u7aef Discourse \u5bb9\u5668\u53ea\u7ed1\u5b9a\u672c\u673a\u7aef\u53e3\uff0c\u4e0d\u76f4\u63a5\u66b4\u9732\u5230\u516c\u7f51\u7aef\u53e3\u3002\\n\\n![ChatArch Agent Community \u9996\u9875](/img/discourse-ai-community/home.png)\\n\\n## \u8fd9\u6b21\u5b9e\u9645\u90e8\u7f72\u4e86\u4ec0\u4e48\\n\\n\u8fd9\u6b21\u4e0d\u662f\u53ea\u5199\u4e86\u4e00\u4e2a\u65b9\u6848\u6587\u6863\uff0c\u800c\u662f\u5728 `zhihong.oray` \u4e0a\u5b8c\u6210\u4e86\u4e00\u5957\u53ef\u8fd0\u884c\u7684 Discourse + AI staging \u670d\u52a1\u3002\\n\\n| \u5c42 | \u5df2\u90e8\u7f72\u5185\u5bb9 | \u8bf4\u660e |\\n| --- | --- | --- |\\n| \u793e\u533a\u754c\u9762 | Discourse | \u4f5c\u4e3a topic\u3001post\u3001category\u3001tag \u7684 comment-based \u793e\u533a\u5c42 |\\n| \u8fd0\u884c\u65b9\u5f0f | \u5b98\u65b9 `discourse_docker` | \u8fd9\u662f Discourse \u5b98\u65b9\u63a8\u8350\u7684\u751f\u4ea7\u90e8\u7f72\u8def\u5f84 |\\n| \u957f\u671f\u76ee\u5f55 | `/home/zhihong/.chatarch/discourse/` | \u6309 ChatArch \u957f\u671f\u670d\u52a1\u76ee\u5f55\u843d\u4f4d\uff0c\u4e0d\u653e\u5728\u4e00\u6b21\u6027 project \u91cc |\\n| \u53cd\u5411\u4ee3\u7406 | Nginx vhost | `discourse.local.wzhecnu.cn` \u53cd\u4ee3\u5230\u672c\u673a Discourse \u5bb9\u5668\u7aef\u53e3 |\\n| HTTPS | \u590d\u7528\u5df2\u6709 wildcard \u8bc1\u4e66 | \u4f7f\u7528\u670d\u52a1\u5668\u73b0\u6709 `local.wzhecnu.cn` \u8bc1\u4e66\u4f53\u7cfb |\\n| AI \u63d2\u4ef6 | bundled Discourse AI | Discourse AI \u73b0\u5728\u5728\u4e3b\u4ed3\u5e93 `plugins/discourse-ai` \u4e2d\u7ef4\u62a4 |\\n| LLM | ChatArch OpenAI-compatible profile | \u5df2\u63a5\u5165 `OpenAI/byted.env` \u5bf9\u5e94\u6a21\u578b\uff0c\u5bc6\u94a5\u53ea\u5199\u5165 Discourse secret |\\n| \u793e\u533a\u7ed3\u6784 | \u5206\u7c7b + \u6807\u7b7e | \u5df2\u521b\u5efa Agent \u793e\u533a\u7b2c\u4e00\u7248\u5206\u7c7b\u548c status/route/agent \u6807\u7b7e |\\n| \u7cfb\u7edf\u8c03\u4f18 | `vm.overcommit_memory = 1` | \u6309 Redis/Discourse \u957f\u671f\u8fd0\u884c\u5efa\u8bae\u6301\u4e45\u5316 |\\n\\n\u6ca1\u6709\u90e8\u7f72\u7684\u90e8\u5206\u4e5f\u8981\u660e\u786e\uff1a\u8fd9\u6b21**\u6ca1\u6709\u90e8\u7f72 Mail Server**\u3002Discourse \u76ee\u524d\u7528 `DISCOURSE_SKIP_EMAIL_SETUP=1` \u5b8c\u6210\u521d\u59cb\u5316\uff0c\u6240\u4ee5\u9875\u9762\u3001\u7ba1\u7406\u5458\u8d26\u53f7\u548c AI \u80fd\u529b\u53ef\u7528\uff0c\u4f46\u9080\u8bf7\u90ae\u4ef6\u3001\u901a\u77e5\u3001\u627e\u56de\u5bc6\u7801\u3001\u90ae\u4ef6\u786e\u8ba4\u8fd8\u4e0d\u80fd\u7b97\u751f\u4ea7\u53ef\u7528\u3002\\n\\n## \u6587\u4ef6\u5199\u5230\u4e86\u54ea\u91cc\\n\\n\u8fd9\u6b21\u5206\u6210\u4e24\u7c7b\u76ee\u5f55\uff1a\u957f\u671f\u670d\u52a1\u76ee\u5f55\u548c\u90e8\u7f72\u8bb0\u5f55\u76ee\u5f55\u3002\\n\\n### \u957f\u671f\u670d\u52a1\u76ee\u5f55\\n\\n\u957f\u671f\u670d\u52a1\u90fd\u653e\u5728 ChatArch \u7684\u9ed8\u8ba4\u76ee\u5f55\u4e0b\uff1a\\n\\n```text\\n/home/zhihong/.chatarch/discourse/\\n```\\n\\n\u91cc\u9762\u7684\u5173\u952e\u8def\u5f84\u662f\uff1a\\n\\n```text\\n/home/zhihong/.chatarch/discourse/docker/\\n/home/zhihong/.chatarch/discourse/docker/containers/app.yml\\n/home/zhihong/.chatarch/discourse/shared/standalone/\\n/home/zhihong/.chatarch/discourse/secrets/\\n/home/zhihong/.chatarch/discourse/backups/\\n/home/zhihong/.chatarch/discourse/logs/\\n```\\n\\n\u5176\u4e2d `secrets/` \u53ea\u653e\u670d\u52a1\u5668\u672c\u5730 secret\uff0c\u6bd4\u5982\u7ba1\u7406\u5458\u5bc6\u7801\u548c\u540e\u7eed\u53ef\u80fd\u63a5\u5165\u7684\u670d\u52a1\u51ed\u636e\u3002\u6587\u7ae0\u91cc\u53ea\u8bb0\u5f55\u8def\u5f84\uff0c\u4e0d\u8bb0\u5f55\u4efb\u4f55\u503c\u3002\\n\\n### Nginx \u548c\u7cfb\u7edf\u914d\u7f6e\\n\\nNginx \u914d\u7f6e\u5199\u5728\uff1a\\n\\n```text\\n/etc/nginx/sites-available/discourse-local.conf\\n/etc/nginx/sites-enabled/discourse-local.conf\\n```\\n\\nRedis/Discourse \u63a8\u8350\u7684\u5185\u6838\u53c2\u6570\u5199\u5728\uff1a\\n\\n```text\\n/etc/sysctl.d/99-chatarch-discourse.conf\\n```\\n\\n### \u90e8\u7f72\u8bb0\u5f55\u76ee\u5f55\\n\\n\u90e8\u7f72\u8fc7\u7a0b\u3001\u9a8c\u8bc1\u65e5\u5fd7\u3001\u62a5\u544a\u548c\u535a\u5ba2 PR \u8bb0\u5f55\u653e\u5728 Playground project \u91cc\uff1a\\n\\n```text\\n/home/zhihong/Playground/projects/agent-community/07-27-discourse-ai-service/\\n```\\n\\n\u8fd9\u4e2a\u76ee\u5f55\u4e0d\u662f\u670d\u52a1\u8fd0\u884c\u76ee\u5f55\uff0c\u53ea\u7528\u4e8e\u8bb0\u5f55\u8fc7\u7a0b\u3002\u4e3b\u8981\u6587\u4ef6\u5305\u62ec\uff1a\\n\\n```text\\nPRD.md\\nprogress.md\\nlinks.md\\nreports/server-inventory.md\\nreports/install-plan.md\\nreports/deployment-log.md\\nreports/verification-report.md\\nplayground/discourse-verify-*.log\\n```\\n\\n## \u9875\u9762\u622a\u56fe\\n\\n\u9996\u9875\u5df2\u7ecf\u80fd\u770b\u5230\u7ad9\u70b9\u6807\u9898\u548c Discourse \u57fa\u7840\u5bfc\u822a\u3002\\n\\n![Discourse \u9996\u9875](/img/discourse-ai-community/home.png)\\n\\n\u5206\u7c7b\u9875\u5c55\u793a\u4e86\u7b2c\u4e00\u7248 Agent \u793e\u533a\u7684\u4e03\u4e2a\u7a7a\u95f4\u3002\\n\\n![Discourse \u5206\u7c7b\u9875](/img/discourse-ai-community/categories.png)\\n\\n\u6807\u7b7e\u9875\u7528\u4e8e\u627f\u8f7d status\u3001route\u3001agent \u7b49\u72b6\u6001\u548c\u8def\u7531\u4fe1\u606f\u3002\\n\\n![Discourse \u6807\u7b7e\u9875](/img/discourse-ai-community/tags.png)\\n\\n## \u8fd9\u4e2a\u793e\u533a\u7528\u6765\u505a\u4ec0\u4e48\\n\\n\u7b2c\u4e00\u7248\u628a\u5b83\u5b9a\u4f4d\u6210 Agent \u793e\u533a\u7684\u8ba8\u8bba\u5c42\uff1a\\n\\n```text\\n\u4eba\u7c7b\u63d0\u51fa\u4efb\u52a1 / \u95ee\u9898 / \u63d0\u6848\\n  -> Discourse topic \u627f\u8f7d\u4e0a\u4e0b\u6587\u548c\u8bc4\u8bba\\n  -> AI helper / AI bot \u53c2\u4e0e\u6458\u8981\u3001\u89e3\u91ca\u3001\u8865\u5145\u5efa\u8bae\\n  -> \u4eba\u7c7b\u786e\u8ba4\u7ed3\u8bba\\n  -> \u540e\u7eed\u518d\u6c89\u6dc0\u5230 ChatBoard discussion \u6216\u9879\u76ee\u6587\u6863\\n```\\n\\n\u5b83\u9002\u5408\u653e\u8fd9\u4e9b\u5185\u5bb9\uff1a\\n\\n- \u4e00\u4e2a\u6a21\u7cca\u4ea7\u54c1\u65b9\u5411\u7684\u63a2\u7d22\u8ba8\u8bba\uff1b\\n- \u4e00\u4e2a\u9879\u76ee\u5386\u53f2\u7684\u68b3\u7406\u548c\u5206\u6d41\uff1b\\n- \u4e00\u4e2a\u90e8\u7f72\u3001\u8fd0\u7ef4\u3001\u5de5\u5177\u96c6\u6210\u95ee\u9898\uff1b\\n- \u4e00\u4e2a\u9700\u8981\u591a\u8f6e\u8bc4\u8bba\u548c\u4eba\u5de5\u786e\u8ba4\u7684\u8bbe\u8ba1\u63d0\u6848\uff1b\\n- \u4e00\u4e2a Agent \u8fd0\u884c\u7ed3\u679c\u7684\u5ba1\u67e5\u4e0e\u6c47\u603b\u3002\\n\\n\u5b83\u4e0d\u9002\u5408\u76f4\u63a5\u627f\u8f7d\u8fd9\u4e9b\u5185\u5bb9\uff1a\\n\\n- \u9700\u8981\u4e25\u683c\u7248\u672c\u63a7\u5236\u7684\u6e90\u7801\uff1b\\n- \u957f\u671f\u552f\u4e00\u4e8b\u5b9e\u6e90\u7684\u914d\u7f6e\u6587\u4ef6\uff1b\\n- \u5bc6\u94a5\u3001token\u3001SMTP \u5bc6\u7801\u3001API key\uff1b\\n- \u5fc5\u987b\u81ea\u52a8\u6267\u884c\u7684\u90e8\u7f72\u811a\u672c\u3002\\n\\n\u8fd9\u4e9b\u4ecd\u7136\u5e94\u8be5\u7559\u5728 Git\u3001ChatArch \u670d\u52a1\u76ee\u5f55\u3001Playground project \u6216\u5bf9\u5e94 secret store \u91cc\u3002\\n\\n## \u5df2\u521d\u59cb\u5316\u7684\u793e\u533a\u7ed3\u6784\\n\\n\u7b2c\u4e00\u7248\u4e0d\u662f\u7a7a\u7ad9\u70b9\uff0c\u5df2\u7ecf\u521d\u59cb\u5316\u4e86\u5206\u7c7b\u548c\u6807\u7b7e\u3002\u5206\u7c7b\u8d1f\u8d23\u628a\u8ba8\u8bba\u5206\u533a\uff0c\u6807\u7b7e\u8d1f\u8d23\u8868\u8fbe\u72b6\u6001\u3001\u8def\u7531\u548c Agent \u89d2\u8272\u3002\\n\\n## \u5206\u7c7b\u600e\u4e48\u7528\\n\\n\u7b2c\u4e00\u7248\u5df2\u7ecf\u5efa\u597d\u8fd9\u4e9b\u5206\u7c7b\uff1a\\n\\n| \u5206\u7c7b | \u7528\u9014 |\\n| --- | --- |\\n| Tasks | \u5177\u4f53\u4efb\u52a1\u3001\u5f85\u529e\u3001\u6267\u884c\u8bf7\u6c42 |\\n| Research | \u8c03\u7814\u3001\u8bc1\u636e\u3001\u884c\u4e1a\u89c2\u5bdf |\\n| Design | \u4ea7\u54c1\u3001\u6d41\u7a0b\u3001\u7cfb\u7edf\u8bbe\u8ba1 |\\n| Decisions | \u5df2\u786e\u8ba4\u7684\u7ed3\u8bba\u3001\u8def\u7ebf\u548c\u51b3\u7b56 |\\n| Agent Runs | Agent \u6267\u884c\u8bb0\u5f55\u3001\u5ba1\u67e5\u3001\u6c47\u62a5 |\\n| Agents | Agent \u89d2\u8272\u3001\u80fd\u529b\u3001\u8fb9\u754c\u548c\u8bf4\u660e |\\n| Meta | \u793e\u533a\u6cbb\u7406\u3001\u914d\u7f6e\u3001\u53cd\u9988\u548c\u89c4\u5219 |\\n\\n\u5efa\u8bae\u8fd9\u6837\u9009\u62e9\u5206\u7c7b\uff1a\\n\\n- \u4e0d\u77e5\u9053\u653e\u54ea\uff1a\u5148\u653e `Tasks` \u6216 `Research`\u3002\\n- \u5df2\u7ecf\u5f62\u6210\u65b9\u6848\uff1a\u653e `Design`\u3002\\n- \u5df2\u88ab\u4eba\u5de5\u63a5\u53d7\uff1a\u653e `Decisions`\u3002\\n- \u662f\u4e00\u6b21 AI/Agent \u6267\u884c\u7ed3\u679c\uff1a\u653e `Agent Runs`\u3002\\n- \u662f\u5728\u5b9a\u4e49\u67d0\u4e2a\u673a\u5668\u4eba\u5e94\u8be5\u600e\u4e48\u5de5\u4f5c\uff1a\u653e `Agents`\u3002\\n\\n## \u6807\u7b7e\u600e\u4e48\u7528\\n\\n\u7b2c\u4e00\u6279\u6807\u7b7e\u5206\u6210\u4e09\u7c7b\u3002\\n\\n### \u72b6\u6001\u6807\u7b7e\\n\\n```text\\nstatus-open\\nstatus-running\\nstatus-waiting-human\\nstatus-accepted\\n```\\n\\n\u5efa\u8bae\u89c4\u5219\uff1a\\n\\n- `status-open`\uff1a\u521a\u63d0\u51fa\uff0c\u8fd8\u6ca1\u6709\u660e\u786e\u5904\u7406\uff1b\\n- `status-running`\uff1a\u5df2\u7ecf\u6709\u4eba\u6216 Agent \u5728\u5904\u7406\uff1b\\n- `status-waiting-human`\uff1a\u7b49\u5f85\u4eba\u5de5\u786e\u8ba4\u3001\u5408\u5e76\u3001\u53d1\u5e03\u6216\u6388\u6743\uff1b\\n- `status-accepted`\uff1a\u7ed3\u8bba\u5df2\u88ab\u63a5\u53d7\uff0c\u53ef\u4ee5\u8fdb\u5165\u6c89\u6dc0\u6216\u6267\u884c\u3002\\n\\n### \u8def\u7531\u6807\u7b7e\\n\\n```text\\nroute-skill\\nroute-infra\\nroute-archive\\n```\\n\\n\u5efa\u8bae\u89c4\u5219\uff1a\\n\\n- `route-skill`\uff1a\u8fd9\u6761\u8ba8\u8bba\u5e94\u63d0\u70bc\u4e3a skill \u6216\u6d41\u7a0b\uff1b\\n- `route-infra`\uff1a\u8fd9\u6761\u8ba8\u8bba\u5e94\u53d8\u6210\u5de5\u5177\u3001\u670d\u52a1\u3001API \u6216\u90e8\u7f72\u80fd\u529b\uff1b\\n- `route-archive`\uff1a\u8fd9\u6761\u8ba8\u8bba\u53ea\u5f52\u6863\uff0c\u4e0d\u7ee7\u7eed\u6267\u884c\u3002\\n\\n### Agent \u6807\u7b7e\\n\\n```text\\nagent-curator\\nagent-critic\\nagent-scribe\\nagent-router\\n```\\n\\n\u5efa\u8bae\u89c4\u5219\uff1a\\n\\n- `agent-curator`\uff1a\u9700\u8981\u6574\u7406\u6750\u6599\u3001\u63d0\u53d6\u8bc1\u636e\uff1b\\n- `agent-critic`\uff1a\u9700\u8981\u5ba1\u67e5\u98ce\u9669\u3001\u6f0f\u6d1e\u3001\u8fc7\u5ea6\u63a8\u65ad\uff1b\\n- `agent-scribe`\uff1a\u9700\u8981\u751f\u6210 final summary\u3001decision log\uff1b\\n- `agent-router`\uff1a\u9700\u8981\u5224\u65ad\u4e0b\u4e00\u6b65\u8be5\u53bb skill\u3001infra\u3001archive \u8fd8\u662f\u65b0 project\u3002\\n\\n## \u53d1\u4e00\u4e2a\u4efb\u52a1 Topic \u7684\u5efa\u8bae\u683c\u5f0f\\n\\n\u53ef\u4ee5\u7528\u4e0b\u9762\u8fd9\u4e2a\u6a21\u677f\u53d1\u5e16\uff1a\\n\\n```markdown\\n## \u80cc\u666f\\n\\n\u6211\u73b0\u5728\u60f3\u89e3\u51b3\u4ec0\u4e48\u95ee\u9898\uff1f\u5df2\u6709\u4e0a\u4e0b\u6587\u5728\u54ea\u91cc\uff1f\\n\\n## \u76ee\u6807\\n\\n\u8fd9\u6b21\u5e0c\u671b\u5f97\u5230\u4ec0\u4e48\u7ed3\u679c\uff1f\u4f8b\u5982\u8c03\u7814\u3001\u65b9\u6848\u3001\u90e8\u7f72\u3001PR\u3001\u6587\u6863\u3001\u51b3\u7b56\u3002\\n\\n## \u8bc1\u636e / \u94fe\u63a5\\n\\n- \u94fe\u63a5 1\\n- \u6587\u4ef6\u6216\u9879\u76ee 2\\n- \u76f8\u5173\u8ba8\u8bba 3\\n\\n## \u5e0c\u671b Agent \u505a\u4ec0\u4e48\\n\\n- Curator\uff1a\u6574\u7406\u5df2\u6709\u6750\u6599\\n- Critic\uff1a\u68c0\u67e5\u98ce\u9669\\n- Scribe\uff1a\u6700\u540e\u603b\u7ed3\u7ed3\u8bba\\n\\n## \u4eba\u7c7b\u786e\u8ba4\u70b9\\n\\n- \u54ea\u4e9b\u52a8\u4f5c\u9700\u8981\u6211\u6700\u540e\u786e\u8ba4\uff1f\\n- \u54ea\u4e9b\u4e8b\u60c5\u4e0d\u80fd\u81ea\u52a8\u6267\u884c\uff1f\\n```\\n\\n\u53d1\u5e16\u540e\u53ef\u4ee5\u5148\u52a0\uff1a\\n\\n```text\\nstatus-open\\ntask\\n```\\n\\n\u5982\u679c\u5f00\u59cb\u6267\u884c\uff0c\u518d\u6539\u6210\uff1a\\n\\n```text\\nstatus-running\\n```\\n\\n\u5982\u679c\u9700\u8981\u4eba\u5de5\u786e\u8ba4\uff0c\u5219\u6539\u6210\uff1a\\n\\n```text\\nstatus-waiting-human\\n```\\n\\n## AI \u90e8\u7f72\u5230\u4e86\u4ec0\u4e48\u7a0b\u5ea6\\n\\n\u5f53\u524d\u5df2\u7ecf\u542f\u7528 Discourse AI\uff0c\u5e76\u914d\u7f6e\u4e86\u4e00\u4e2a\u9ed8\u8ba4 LLM\u3002\u7b2c\u4e00\u7248\u5efa\u8bae\u628a\u5b83\u5f53\u4f5c\u793e\u533a\u5185\u7f6e AI \u52a9\u624b\uff0c\u800c\u4e0d\u662f\u5b8c\u6574 Agent Router\u3002\\n\\n\u5f53\u524d AI \u72b6\u6001\u662f\uff1a\\n\\n```text\\nDiscourse AI plugin: enabled\\nAI helper: enabled\\nAI bot: enabled\\nDefault LLM: configured\\nContainer-to-LLM test: HTTP 200\\nCompanion bot user: ark-code-latest1\\n```\\n\\n\u8fd9\u91cc\u7684 API key \u6ca1\u6709\u5199\u8fdb\u535a\u5ba2\u3001project \u6587\u6863\u6216\u547d\u4ee4\u8f93\u51fa\uff0c\u800c\u662f\u5199\u8fdb Discourse \u81ea\u5df1\u7684 `AiSecret`\u3002\u4e5f\u5c31\u662f\u8bf4\uff0c\u6587\u7ae0\u53ef\u4ee5\u8bf4\u660e\u201c\u63a5\u4e86\u54ea\u4e2a profile \u548c\u54ea\u4e2a\u6a21\u578b\u201d\uff0c\u4f46\u4e0d\u80fd\u516c\u5f00 secret \u503c\u3002\\n\\n\u53ef\u4ee5\u4f18\u5148\u4f7f\u7528\u8fd9\u4e9b\u80fd\u529b\uff1a\\n\\n- \u5bf9\u957f topic \u505a\u6458\u8981\uff1b\\n- \u5e2e\u5fd9\u6539\u5199\u6807\u9898\u548c\u6b63\u6587\uff1b\\n- \u5bf9\u4e00\u6bb5\u8ba8\u8bba\u63d0\u70bc\u884c\u52a8\u9879\uff1b\\n- \u8ba9 AI bot \u5728 topic \u4e2d\u63d0\u4f9b\u4e00\u4e2a\u7ed3\u6784\u5316\u56de\u590d\uff1b\\n- \u5728\u5199 proposal \u65f6\u8ba9 AI \u5148\u751f\u6210\u8349\u7a3f\uff0c\u518d\u7531\u4eba\u4fee\u6539\u3002\\n\\n\u4f7f\u7528\u539f\u5219\uff1a\\n\\n- AI \u56de\u590d\u8981\u77ed\uff0c\u4e0d\u8981\u5237\u5c4f\uff1b\\n- AI \u8f93\u51fa\u8981\u5f15\u7528\u5b83\u4f9d\u636e\u7684\u4e0a\u4e0b\u6587\uff1b\\n- \u6d89\u53ca\u90e8\u7f72\u3001\u5220\u9664\u3001\u53d1\u5e03\u3001\u6743\u9650\u3001\u8d39\u7528\u3001\u5bc6\u94a5\u7684\u52a8\u4f5c\u5fc5\u987b\u4eba\u5de5\u786e\u8ba4\uff1b\\n- \u6700\u7ec8\u7ed3\u8bba\u5e94\u8be5\u7531\u4eba\u7c7b\u63a5\u53d7\uff0c\u7136\u540e\u518d\u6c89\u6dc0\u5230 `Decisions` \u6216 ChatBoard discussion\u3002\\n\\n## \u63a8\u8350\u7684\u8ba8\u8bba\u95ed\u73af\\n\\n\u4e00\u4e2a\u5b8c\u6574 topic \u6700\u597d\u8d70\u6210\u8fd9\u6837\uff1a\\n\\n```text\\n1. \u4eba\u53d1\u8d77 topic\uff0c\u8bf4\u660e\u80cc\u666f\u548c\u76ee\u6807\\n2. \u52a0 category \u548c tags\\n3. AI / Agent \u5e2e\u5fd9\u6574\u7406\u4fe1\u606f\u6216\u63d0\u51fa\u65b9\u6848\\n4. Critic \u89c6\u89d2\u68c0\u67e5\u98ce\u9669\\n5. Scribe \u89c6\u89d2\u751f\u6210 final proposal\\n6. \u4eba\u7c7b\u56de\u590d accepted / revise / reject\\n7. accepted \u7684\u7ed3\u8bba\u8fdb\u5165 Decisions \u6216\u540c\u6b65\u5230 ChatBoard discussion\\n```\\n\\n\u8fd9\u6bd4\u666e\u901a\u804a\u5929\u66f4\u9002\u5408\u4f5c\u4e3a\u957f\u671f\u77e5\u8bc6\u6c89\u6dc0\uff0c\u56e0\u4e3a\u6bcf\u4e2a topic \u90fd\u6709\u72b6\u6001\u3001\u8def\u7531\u3001\u7ed3\u8bba\u548c\u8d23\u4efb\u8fb9\u754c\u3002\\n\\n## Mail Server / SMTP \u72b6\u6001\\n\\n\u7b2c\u4e00\u7248\u4ecd\u6709\u4e00\u4e2a\u91cd\u8981\u7f3a\u53e3\uff1aSMTP \u8fd8\u6ca1\u6709\u914d\u7f6e\uff0c\u800c\u4e14\u8fd9\u6b21\u6ca1\u6709\u90e8\u7f72 Mail Server\u3002\\n\\n\u8fd9\u610f\u5473\u7740\uff1a\\n\\n- \u7ad9\u70b9\u53ef\u4ee5\u5185\u90e8\u8bbf\u95ee\u548c\u6d4b\u8bd5\uff1b\\n- \u7ba1\u7406\u5458\u8d26\u53f7\u5df2\u7ecf\u53ef\u7528\uff1b\\n- AI \u63d2\u4ef6\u548c\u9ed8\u8ba4 LLM \u5df2\u53ef\u7528\uff1b\\n- \u4f46\u9080\u8bf7\u90ae\u4ef6\u3001\u901a\u77e5\u3001\u627e\u56de\u5bc6\u7801\u3001\u90ae\u4ef6\u786e\u8ba4\u7b49\u80fd\u529b\u8fd8\u4e0d\u80fd\u89c6\u4e3a\u751f\u4ea7\u53ef\u7528\u3002\\n\\n\u4e3a\u4ec0\u4e48\u53ef\u4ee5\u5148\u4e0d\u90e8\u7f72 Mail Server\uff1f\u56e0\u4e3a\u8fd9\u6b21\u76ee\u6807\u662f\u5148\u9a8c\u8bc1 Discourse + AI \u8ba8\u8bba\u793e\u533a\u672c\u4f53\u3002Discourse \u53ef\u4ee5\u7528 `DISCOURSE_SKIP_EMAIL_SETUP=1` \u5b8c\u6210 staging \u521d\u59cb\u5316\uff0c\u518d\u901a\u8fc7 Rails \u4efb\u52a1\u521b\u5efa\u7ba1\u7406\u5458\u8d26\u53f7\u3002\u8fd9\u6837\u80fd\u5148\u628a\u9875\u9762\u3001\u5206\u7c7b\u3001\u6807\u7b7e\u3001AI \u63d2\u4ef6\u548c LLM \u8d70\u901a\u3002\\n\\n\u751f\u4ea7\u5316\u4e4b\u524d\u9700\u8981\u8865 SMTP\u3002\u6700\u5c11\u9700\u8981\u8fd9\u4e9b\u4fe1\u606f\uff1a\\n\\n| \u9879 | \u8bf4\u660e |\\n| --- | --- |\\n| SMTP host | \u4f8b\u5982 `smtp.example.com` \u6216 `mail.example.com` |\\n| SMTP port | \u901a\u5e38\u662f `587` STARTTLS\uff0c\u6216 `465` implicit TLS |\\n| TLS \u6a21\u5f0f | STARTTLS / implicit TLS / provider-specific |\\n| SMTP username | \u53d1\u4fe1\u8d26\u53f7 |\\n| SMTP password | \u5bc6\u7801\u6216 app password\uff0c\u53ea\u80fd\u8fdb secret\uff0c\u4e0d\u80fd\u5199\u6587\u6863 |\\n| notification email | Discourse \u7cfb\u7edf\u901a\u77e5\u53d1\u4ef6\u4eba |\\n| reply-to \u7b56\u7565 | \u662f\u5426\u5141\u8bb8\u90ae\u4ef6\u56de\u590d\u8fdb\u5165 Discourse |\\n\\n\u5982\u679c\u8981\u81ea\u5efa `docker-mailserver`\uff0c\u8fd8\u9700\u8981\u66f4\u591a DNS \u548c\u6295\u9012\u914d\u7f6e\uff1a\\n\\n| \u9879 | \u8bf4\u660e |\\n| --- | --- |\\n| Mail \u57df\u540d | \u4f8b\u5982 `mail.example.com` |\\n| A / MX \u8bb0\u5f55 | \u8ba9\u5916\u90e8\u80fd\u627e\u5230 mail host |\\n| PTR / rDNS | \u5f71\u54cd\u6295\u9012\u4fe1\u8a89\uff0c\u901a\u5e38\u9700\u8981\u4e91\u5382\u5546\u6216\u7f51\u7edc\u63d0\u4f9b\u65b9\u652f\u6301 |\\n| SPF | \u58f0\u660e\u5141\u8bb8\u54ea\u4e9b\u670d\u52a1\u5668\u4ee3\u8868\u57df\u540d\u53d1\u4fe1 |\\n| DKIM | \u90ae\u4ef6\u7b7e\u540d\uff0cDMS \u9700\u8981\u751f\u6210\u5e76\u53d1\u5e03 DNS \u8bb0\u5f55 |\\n| DMARC | \u6307\u5b9a SPF/DKIM \u5931\u8d25\u65f6\u7684\u7b56\u7565 |\\n| \u7aef\u53e3\u7b56\u7565 | 25/465/587 \u662f\u5426\u5f00\u653e\u3001\u662f\u5426\u88ab\u4e91\u5382\u5546\u9650\u5236 |\\n| \u8bc1\u4e66 | `mail.example.com` \u7684 TLS \u8bc1\u4e66 |\\n\\n\u6240\u4ee5 Mail Server \u4e0d\u662f\u5b8c\u5168\u4e0d\u9700\u8981\uff0c\u800c\u662f**\u4e0d\u5e94\u8be5\u4f5c\u4e3a\u7b2c\u4e00\u6b65\u963b\u585e Discourse + AI \u793e\u533a\u9a8c\u8bc1**\u3002\u66f4\u7a33\u59a5\u7684\u987a\u5e8f\u662f\uff1a\\n\\n```text\\n1. \u5148\u8dd1\u901a Discourse + AI + \u5206\u7c7b/\u6807\u7b7e\\n2. \u518d\u63a5\u4e00\u4e2a\u53ef\u9760 SMTP\uff0c\u8ba9\u9080\u8bf7\u548c\u901a\u77e5\u53ef\u7528\\n3. \u5982\u679c\u786e\u5b9a\u8981 full self-host mail\uff0c\u518d\u5355\u72ec\u90e8\u7f72 DMS\\n```\\n\\n## \u8fd8\u9700\u8981\u786e\u8ba4\u4ec0\u4e48\\n\\nSMTP \u4e4b\u5916\uff0c\u8fd8\u9700\u8981\u51e0\u4e2a\u4ea7\u54c1\u548c\u8fd0\u7ef4\u51b3\u7b56\uff1a\\n\\n| \u51b3\u7b56 | \u4e3a\u4ec0\u4e48\u9700\u8981 |\\n| --- | --- |\\n| \u8bbf\u95ee\u8303\u56f4 | \u53ea\u5185\u7f51\u3001VPN\u3001local \u57df\u540d\uff0c\u8fd8\u662f\u540e\u7eed\u516c\u5f00\u57df\u540d |\\n| \u6ce8\u518c\u7b56\u7565 | \u9080\u8bf7\u5236\u3001\u7ba1\u7406\u5458\u521b\u5efa\u8d26\u53f7\uff0c\u8fd8\u662f\u5f00\u653e\u6ce8\u518c |\\n| \u5907\u4efd\u7b56\u7565 | Discourse \u5907\u4efd\u4fdd\u5b58\u5728\u54ea\u91cc\u3001\u4fdd\u7559\u591a\u4e45\u3001\u662f\u5426\u5f02\u5730\u5907\u4efd |\\n| AI \u9884\u7b97 | LLM \u6bcf\u65e5/\u6bcf\u6708\u6210\u672c\u4e0a\u9650\u3001\u54ea\u4e9b\u7528\u6237\u53ef\u7528 AI |\\n| Agent Router | \u662f\u5426\u8981\u8ba9\u5916\u90e8 Agent \u76d1\u542c topic/tag \u5e76\u81ea\u52a8\u56de\u590d |\\n| \u5ba1\u6279\u8fb9\u754c | \u54ea\u4e9b\u56de\u590d\u53ef\u4ee5\u81ea\u52a8\u53d1\uff0c\u54ea\u4e9b\u5fc5\u987b\u4eba\u7c7b\u786e\u8ba4 |\\n\\n## \u540e\u7eed\u6f14\u8fdb\\n\\n\u8fd9\u6b21\u90e8\u7f72\u5148\u5b8c\u6210\u7684\u662f Discourse + AI \u793e\u533a\u5c42\u3002\u4e0b\u4e00\u6b65\u53ef\u4ee5\u7ee7\u7eed\u505a\uff1a\\n\\n- \u914d\u7f6e SMTP\uff0c\u8ba9\u9080\u8bf7\u548c\u901a\u77e5\u53ef\u7528\uff1b\\n- \u5199\u4e00\u4e2a Agent Router\uff0c\u76d1\u542c topic\u3001tag \u548c mention\uff1b\\n- \u628a accepted topic \u540c\u6b65\u5230 ChatBoard discussion\uff1b\\n- \u7ed9\u6bcf\u7c7b Agent \u5efa\u7acb\u56fa\u5b9a\u56de\u590d\u683c\u5f0f\uff1b\\n- \u589e\u52a0\u5ba1\u8ba1\u65e5\u5fd7\u3001\u6210\u672c\u63a7\u5236\u548c human approval gate\u3002\\n\\n\u957f\u671f\u76ee\u6807\u4e0d\u662f\u201c\u6709\u4e00\u4e2a\u8bba\u575b\u201d\uff0c\u800c\u662f\u5f62\u6210\u4e00\u4e2a\u53ef\u90e8\u7f72\u7684 Agent \u8bae\u4e8b\u5385\uff1a\u4eba\u7c7b\u3001\u673a\u5668\u4eba\u548c\u5de5\u5177\u5728\u540c\u4e00\u4e2a\u8bc4\u8bba\u7a7a\u95f4\u91cc\u56f4\u7ed5\u4efb\u52a1\u534f\u4f5c\uff0c\u5e76\u628a\u7ed3\u8bba\u6c89\u6dc0\u6210\u53ef\u4ee5\u7ee7\u7eed\u6267\u884c\u7684\u9879\u76ee\u3001\u6587\u6863\u3001PR \u6216\u51b3\u7b56\u3002"},{"id":"hermes-multi-agent-profile-subagent-kanban","metadata":{"permalink":"/ChatBlog/dev/blog/hermes-multi-agent-profile-subagent-kanban","editUrl":"https://github.com/ChatArch/ChatBlog/tree/main/blog/2026-07-25-hermes-multi-agent.mdx","source":"@site/blog/2026-07-25-hermes-multi-agent.mdx","title":"Hermes Multi-Agent\uff1aProfile\u3001Subagent \u4e0e Kanban \u7684\u4e09\u5c42\u534f\u4f5c\u6a21\u578b","description":"\u4ece\u6e90\u7801\u68b3\u7406 Hermes \u5982\u4f55\u7528 Profile\u3001delegate_task\u3001Kanban\u3001Gateway multiplex \u548c terminal backend \u7ec4\u5408\u51fa\u4e0d\u540c\u4eba\u683c\u3001\u4e0d\u540c\u8bb0\u5fc6\u4e0e\u4e0d\u540c\u6267\u884c\u73af\u5883\u7684\u591a Agent \u7cfb\u7edf\u3002","date":"2026-07-25T00:00:00.000Z","tags":[{"inline":true,"label":"hermes","permalink":"/ChatBlog/dev/blog/tags/hermes"},{"inline":true,"label":"agent","permalink":"/ChatBlog/dev/blog/tags/agent"},{"inline":true,"label":"multi-agent","permalink":"/ChatBlog/dev/blog/tags/multi-agent"},{"inline":true,"label":"profile","permalink":"/ChatBlog/dev/blog/tags/profile"},{"inline":true,"label":"kanban","permalink":"/ChatBlog/dev/blog/tags/kanban"}],"readingTime":14.05,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Hermes Multi-Agent\uff1aProfile\u3001Subagent \u4e0e Kanban \u7684\u4e09\u5c42\u534f\u4f5c\u6a21\u578b","date":"2026-07-25T00:00:00.000Z","slug":"hermes-multi-agent-profile-subagent-kanban","tags":["hermes","agent","multi-agent","profile","kanban"],"description":"\u4ece\u6e90\u7801\u68b3\u7406 Hermes \u5982\u4f55\u7528 Profile\u3001delegate_task\u3001Kanban\u3001Gateway multiplex \u548c terminal backend \u7ec4\u5408\u51fa\u4e0d\u540c\u4eba\u683c\u3001\u4e0d\u540c\u8bb0\u5fc6\u4e0e\u4e0d\u540c\u6267\u884c\u73af\u5883\u7684\u591a Agent \u7cfb\u7edf\u3002"},"unlisted":false,"prevItem":{"title":"ChatArch Agent Community\uff1aDiscourse + AI \u793e\u533a\u4f7f\u7528\u8bf4\u660e","permalink":"/ChatBlog/dev/blog/chatarch-discourse-ai-community-usage"},"nextItem":{"title":"Hello World\uff1aChatBlog \u6846\u67b6\u80fd\u529b\u5c55\u793a","permalink":"/ChatBlog/dev/blog/hello-world-writing-public-notes-with-chatblog"}},"content":"Hermes \u4e0d\u662f\u7528\u4e00\u4e2a\u5355\u4e00\u7684\u201c\u591a\u667a\u80fd\u4f53\u5f00\u5173\u201d\u6765\u5b9e\u73b0 Multi-Agent\uff0c\u800c\u662f\u628a\u80fd\u529b\u62c6\u6210\u51e0\u5c42\uff1aProfile \u8d1f\u8d23\u957f\u671f\u8eab\u4efd\uff0c`delegate_task` \u8d1f\u8d23\u4e34\u65f6\u5e76\u884c\uff0cKanban \u8d1f\u8d23\u6301\u4e45\u534f\u4f5c\uff0cGateway multiplex \u8d1f\u8d23\u591a\u5165\u53e3\u8def\u7531\uff0cterminal backend \u8d1f\u8d23\u628a\u6267\u884c\u9762\u653e\u5230\u672c\u5730\u3001\u5bb9\u5668\u3001SSH \u6216\u4e91\u73af\u5883\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n:::tip \u4e00\u53e5\u8bdd\u7ed3\u8bba\\n\u5982\u679c\u76ee\u6807\u662f\u201c\u4e0d\u540c\u4e2a\u6027\u3001\u4e0d\u540c\u8bb0\u5fc6\u3001\u957f\u671f\u5206\u5de5\u7684\u591a\u4e2a Agent\u201d\uff0c\u7528 **Profile + Kanban**\uff1b\u5982\u679c\u53ea\u662f\u201c\u4e00\u6b21\u5bf9\u8bdd\u91cc\u5e76\u884c\u67e5\u51e0\u4e2a\u65b9\u5411\u201d\uff0c\u7528 **`delegate_task`**\uff1b\u5982\u679c\u8981\u201c\u4e0d\u540c\u673a\u5668\u6267\u884c\u201d\uff0c\u7ed9\u5bf9\u5e94 profile \u6216 session \u914d **SSH / Docker / Modal / Daytona** \u7b49 terminal backend\u3002\\n:::\\n\\n## \u5148\u628a\u51e0\u4e2a\u6982\u5ff5\u5206\u5f00\\n\\nHermes \u91cc\u7684 Multi-Agent \u81f3\u5c11\u6709\u4e94\u4e2a\u76f8\u5173\u6982\u5ff5\uff0c\u5b83\u4eec\u89e3\u51b3\u7684\u95ee\u9898\u4e0d\u540c\uff1a\\n\\n| \u5c42\u7ea7 | \u673a\u5236 | \u89e3\u51b3\u4ec0\u4e48 | \u751f\u547d\u5468\u671f | \u662f\u5426\u6709\u72ec\u7acb\u4eba\u683c/\u8bb0\u5fc6 |\\n| --- | --- | --- | --- | --- |\\n| \u957f\u671f\u8eab\u4efd | Profile | \u72ec\u7acb\u914d\u7f6e\u3001\u4eba\u683c\u3001\u8bb0\u5fc6\u3001\u6280\u80fd\u3001\u4f1a\u8bdd\u3001\u5bc6\u94a5 | \u957f\u671f | \u662f |\\n| \u4e34\u65f6\u5e76\u884c | `delegate_task` subagent | \u540c\u4e00\u6b21\u4efb\u52a1\u5185\u5e76\u884c\u63a8\u7406\u6216\u5c40\u90e8\u63a2\u7d22 | \u5355\u6b21\u4efb\u52a1 | \u9ed8\u8ba4\u4e0d\u662f |\\n| \u6301\u4e45\u534f\u4f5c | Kanban | \u591a profile \u4e4b\u95f4\u7528\u4efb\u52a1\u677f\u4ea4\u63a5\u3001\u91cd\u8bd5\u3001\u5ba1\u8ba1 | \u8de8\u8fdb\u7a0b\u3001\u8de8\u5929 | \u662f\uff0c\u6309 assignee profile |\\n| \u591a\u5165\u53e3\u8def\u7531 | Gateway multiplex | \u4e00\u4e2a gateway \u540c\u65f6\u670d\u52a1\u591a\u4e2a profile | gateway \u8fdb\u7a0b\u671f | \u662f\uff0c\u6309\u8def\u7531 profile |\\n| \u6267\u884c\u73af\u5883 | terminal backend / SSH mode | \u628a terminal\u3001file\u3001code \u5de5\u5177\u653e\u5230\u672c\u673a\u3001\u5bb9\u5668\u3001\u8fdc\u7aef\u6216\u4e91 | profile \u6216 session \u7ea7 | \u4e0d\u76f4\u63a5\u51b3\u5b9a\u4eba\u683c |\\n\\n\u53ef\u4ee5\u628a\u5b83\u7406\u89e3\u6210\u4e0b\u9762\u8fd9\u5f20\u56fe\uff1a\\n\\n```mermaid\\nflowchart TB\\n  U[\u7528\u6237 / \u5e73\u53f0\u6d88\u606f / CLI] --\x3e G[Gateway \u6216 CLI]\\n\\n  subgraph Identity[\u957f\u671f\u8eab\u4efd\u5c42\uff1aProfile]\\n    P1[default profile]\\n    P2[researcher profile]\\n    P3[writer profile]\\n  end\\n\\n  G --\x3e|\u666e\u901a\u4f1a\u8bdd| P1\\n  G --\x3e|multiplex \u8def\u7531| P2\\n  G --\x3e|multiplex \u8def\u7531| P3\\n\\n  subgraph Short[\u4e34\u65f6\u5e76\u884c\u5c42\uff1adelegate_task]\\n    S1[subagent A]\\n    S2[subagent B]\\n  end\\n\\n  P1 --\x3e|\u4e00\u6b21 turn \u5185 fork| S1\\n  P1 --\x3e|\u4e00\u6b21 turn \u5185 fork| S2\\n\\n  subgraph Durable[\u6301\u4e45\u534f\u4f5c\u5c42\uff1aKanban]\\n    K[(kanban.db)]\\n    W1[worker: hermes -p researcher]\\n    W2[worker: hermes -p writer]\\n  end\\n\\n  P1 --\x3e|kanban_create| K\\n  K --\x3e|assignee=researcher| W1\\n  K --\x3e|assignee=writer| W2\\n\\n  subgraph Runtime[\u6267\u884c\u73af\u5883]\\n    L[local]\\n    D[docker]\\n    H[ssh]\\n    M[modal / daytona]\\n  end\\n\\n  P2 --\x3e Runtime\\n  W1 --\x3e Runtime\\n  W2 --\x3e Runtime\\n```\\n\\n\u8fd9\u7bc7\u6587\u7ae0\u6309\u6e90\u7801\u8def\u5f84\u89e3\u91ca\u8fd9\u4e9b\u5c42\u600e\u4e48\u914d\u5408\u3002\\n\\n## Profile\uff1a\u771f\u6b63\u7684\u957f\u671f Agent \u8eab\u4efd\\n\\nProfile \u662f Hermes \u7684\u957f\u671f\u591a Agent \u57fa\u7840\u3002\u6e90\u7801\u6ce8\u91ca\u76f4\u63a5\u628a\u5b83\u5b9a\u4e49\u6210\u201c\u591a\u4e2a\u9694\u79bb Hermes \u5b9e\u4f8b\u201d\u7684\u7ba1\u7406\u5c42\uff1a\u6bcf\u4e2a profile \u90fd\u662f\u4e00\u4e2a\u72ec\u7acb `HERMES_HOME`\uff0c\u62e5\u6709\u81ea\u5df1\u7684 `config.yaml`\u3001`.env`\u3001memory\u3001sessions\u3001skills\u3001gateway\u3001cron \u548c logs\u3002\u5bf9\u5e94\u4ee3\u7801\u5728 `hermes_cli/profiles.py:1`\u3002\\n\\n\u9ed8\u8ba4 profile \u662f\u6839\u76ee\u5f55\u672c\u8eab\uff0cnamed profile \u5728 `profiles/<name>/` \u4e0b\u3002`get_profile_dir()` \u628a `default` \u6620\u5c04\u5230\u9ed8\u8ba4 Hermes home\uff0c\u628a named profile \u6620\u5c04\u5230 profiles \u76ee\u5f55\uff0c\u89c1 `hermes_cli/profiles.py:367`\u3002\\n\\n\u521b\u5efa\u4e00\u4e2a profile \u65f6\uff0cHermes \u4f1a\u521d\u59cb\u5316\u4e00\u7ec4\u76ee\u5f55\uff1a\\n\\n```text\\nmemories/\\nsessions/\\nskills/\\nskins/\\nlogs/\\nplans/\\nworkspace/\\ncron/\\nhome/\\n```\\n\\n\u8fd9\u7ec4\u76ee\u5f55\u5b9a\u4e49\u5728 `hermes_cli/profiles.py:39`\u3002\u4e5f\u5c31\u662f\u8bf4\uff0cprofile \u4e0d\u662f\u4e00\u4e2a\u6807\u7b7e\uff0c\u800c\u662f\u4e00\u5957\u5b8c\u6574\u72b6\u6001\u76ee\u5f55\u3002\\n\\n### \u4eba\u683c\uff1a`SOUL.md`\\n\\nProfile \u7684\u4eba\u683c\u4e3b\u8981\u6765\u81ea profile-local `SOUL.md`\u3002\u7528\u6237\u6587\u6863\u4e5f\u660e\u786e\u8bf4\uff1a`--clone` \u4f1a\u590d\u5236 `config.yaml`\u3001`.env`\u3001`SOUL.md` \u548c skills\uff1b\u5982\u679c\u8981\u4e0d\u540c personality\uff0c\u53ef\u4ee5\u7f16\u8f91\u76ee\u6807 profile \u7684 `SOUL.md`\uff0c\u89c1 `website/docs/user-guide/profiles.md:47`\u3002\\n\\n\u7cfb\u7edf\u63d0\u793a\u6784\u5efa\u65f6\u4f1a\u4ece\u5f53\u524d `get_hermes_home()/SOUL.md` \u8bfb\u53d6\u8eab\u4efd\u5185\u5bb9\u3002\u8fd9\u6837 `researcher` \u548c `writer` \u53ef\u4ee5\u62e5\u6709\u4e0d\u540c\u7684\u53d9\u8ff0\u98ce\u683c\u3001\u804c\u8d23\u8fb9\u754c\u548c\u9ed8\u8ba4\u884c\u4e3a\u3002\\n\\n### \u8bb0\u5fc6\uff1a`memories/MEMORY.md` \u4e0e `memories/USER.md`\\n\\n\u5185\u7f6e\u8bb0\u5fc6\u4e5f\u8ddf\u968f profile\u3002`memory_tool` \u4f7f\u7528\u5f53\u524d `get_hermes_home()/memories`\uff0c\u800c\u4e0d\u662f import \u65f6\u56fa\u5b9a\u4e00\u4e2a\u5168\u5c40\u8def\u5f84\u3002\u8fd9\u662f profile \u9694\u79bb\u5f88\u5173\u952e\u7684\u4e00\u70b9\uff1a\u4e0d\u540c profile \u7684 `MEMORY.md` / `USER.md` \u4e0d\u4f1a\u81ea\u7136\u6df7\u5230\u4e00\u8d77\u3002\\n\\n\u5916\u90e8 memory provider \u4e5f\u662f profile \u53ef\u914d\u7f6e\u7684\u3002\u4ee5 Honcho \u4e3a\u4f8b\uff0c\u6587\u6863\u660e\u786e\u63d0\u5230 multi-agent profiles \u4f1a\u7528\u4e0d\u540c peer profiles \u9694\u79bb AI peer \u7684\u89c2\u5bdf\u4e0e\u7ed3\u8bba\uff0c\u907f\u514d\u4e0d\u540c agent \u7684\u4e0a\u4e0b\u6587\u4ea4\u53c9\u6c61\u67d3\uff0c\u89c1 `website/docs/user-guide/features/honcho.md:31`\u3002\\n\\n### \u914d\u7f6e\u4e0e\u5bc6\u94a5\uff1a`config.yaml` / `.env`\\n\\n\u6bcf\u4e2a profile \u6709\u81ea\u5df1\u7684 `config.yaml` \u4e0e `.env`\u3002\u8fd9\u4f7f\u5f97\u4e0d\u540c Agent \u53ef\u4ee5\u7528\u4e0d\u540c\u6a21\u578b\u3001\u4e0d\u540c\u5de5\u5177\u96c6\u3001\u4e0d\u540c terminal backend\u3001\u4e0d\u540c bot token \u6216 API key\u3002\\n\\n\u591a profile gateway multiplex \u65f6\uff0c\u5bc6\u94a5\u9694\u79bb\u66f4\u4e25\u683c\uff1a`agent/secret_scope.py` \u660e\u786e\u8bf4\u660e\u4e0d\u80fd\u628a\u6240\u6709 profile \u7684 `.env` union \u5230\u8fdb\u7a0b\u5168\u5c40 `os.environ`\uff0c\u5426\u5219 profile A \u7684 key \u53ef\u80fd\u6cc4\u6f0f\u7ed9 profile B\u3002\u5b83\u63d0\u4f9b\u4e86 context-local secret scope\uff0c\u5e76\u5728 multiplex active \u4f46\u65e0 scope \u65f6 fail-closed\uff0c\u89c1 `agent/secret_scope.py:1` \u548c `agent/secret_scope.py:123`\u3002\\n\\n\u5177\u4f53 per-turn scope \u5728 `gateway/run.py:_profile_runtime_scope`\uff1a\\n\\n- `set_hermes_home_override(profile_home)`\uff1a\u628a `get_hermes_home()` \u6307\u5411\u5f53\u524d\u8def\u7531 profile\uff1b\\n- `set_secret_scope(build_profile_secret_scope(profile_home))`\uff1a\u628a\u8be5 profile \u7684 `.env` \u4f5c\u4e3a\u5f53\u524d context \u7684\u5bc6\u94a5\u6765\u6e90\uff1b\\n- \u7ed3\u675f\u65f6 reset \u4e24\u4e2a contextvar\u3002\\n\\n\u4ee3\u7801\u5165\u53e3\u5728 `gateway/run.py:1441`\u3002\\n\\n### \u4f1a\u8bdd\u4e0e skills\uff1a\u4e5f\u968f profile\\n\\n\u4f1a\u8bdd\u6570\u636e\u5e93\u9ed8\u8ba4\u662f\u5f53\u524d `HERMES_HOME/state.db`\uff0cskills \u76ee\u5f55\u4e5f\u662f\u5f53\u524d `HERMES_HOME/skills`\u3002\u56e0\u6b64\u4e00\u4e2a profile \u7684\u4f1a\u8bdd\u5386\u53f2\u3001\u957f\u671f\u6280\u80fd\u548c prompt snapshot \u90fd\u53ef\u4ee5\u72ec\u7acb\u6f14\u5316\u3002\\n\\n\u8fd9\u5c31\u662f\u4e3a\u4ec0\u4e48 Profile \u624d\u662f Hermes \u91cc\u201c\u771f\u6b63\u7684\u957f\u671f Agent\u201d\uff1a\u5b83\u6709\u540d\u5b57\u3001\u6709\u8eab\u4efd\u3001\u6709\u8bb0\u5fc6\u3001\u6709\u914d\u7f6e\u3001\u6709\u5bc6\u94a5\u3001\u6709\u6280\u80fd\u3001\u6709\u4f1a\u8bdd\u3002\\n\\n## `delegate_task`\uff1a\u4e34\u65f6 subagent\uff0c\u800c\u4e0d\u662f\u53e6\u4e00\u4e2a profile\\n\\n`delegate_task` \u662f Hermes \u7684\u77ed\u671f\u5e76\u884c\u673a\u5236\u3002\u5b83\u7528\u4e8e\u4e00\u6b21\u5bf9\u8bdd\u6216\u4e00\u6b21\u4efb\u52a1\u4e2d\uff0c\u628a\u82e5\u5e72\u5b50\u4efb\u52a1\u5206\u7ed9\u4e34\u65f6\u5b50 Agent \u505a\uff0c\u6700\u540e\u628a summary \u56de\u6d41\u7ed9\u7236 Agent\u3002\\n\\n\u6e90\u7801\u6587\u4ef6 `tools/delegate_tool.py` \u7684\u5f00\u5934\u8bf4\u660e\u4e86\u8bbe\u8ba1\u76ee\u6807\uff1a\u5b50 Agent \u6709 fresh conversation\u3001\u81ea\u5df1\u7684 task id\u3001\u53d7\u9650 toolset\u3001\u805a\u7126\u7684 system prompt\uff1b\u7236 Agent \u53ea\u770b\u5230\u6700\u7ec8 summary\uff0c\u770b\u4e0d\u5230\u5b50 Agent \u7684\u4e2d\u95f4\u5de5\u5177\u8c03\u7528\uff0c\u89c1 `tools/delegate_tool.py:1`\u3002\\n\\n### \u5b50 Agent \u600e\u4e48\u521b\u5efa\\n\\n`_build_child_agent()` \u4f1a\u6784\u9020\u4e00\u4e2a\u65b0\u7684 `AIAgent`\uff0c\u5e76\u4f20\u5165\uff1a\\n\\n- child prompt\uff1a\u7531 goal + context \u62fc\u51fa\uff1b\\n- `quiet_mode=True`\uff1b\\n- `platform=\\"subagent\\"`\uff1b\\n- `skip_context_files=True`\uff1b\\n- `skip_memory=True`\uff1b\\n- `parent_session_id`\uff1a\u6307\u5411\u7236 session\uff1b\\n- `enabled_toolsets`\uff1a\u4ece\u7236 Agent \u5de5\u5177\u96c6\u7ee7\u627f\u5e76\u8fc7\u6ee4\u3002\\n\\n\u5173\u952e\u8c03\u7528\u5728 `tools/delegate_tool.py:1050` \u5230 `tools/delegate_tool.py:1350` \u4e00\u5e26\u3002\\n\\n\u8fd9\u91cc\u7684 `skip_memory=True` \u5f88\u5173\u952e\uff1asubagent \u9ed8\u8ba4\u4e0d\u662f\u4e00\u4e2a\u957f\u671f profile identity\uff0c\u5b83\u4e0d\u4f1a\u81ea\u7136\u5e26\u7740\u81ea\u5df1\u7684 `SOUL.md` \u548c\u957f\u671f memory \u751f\u6d3b\u3002\u5b83\u66f4\u50cf\u662f\u7236 Agent \u5728\u4e00\u6b21\u4efb\u52a1\u91cc\u4e34\u65f6 fork \u51fa\u6765\u7684\u533f\u540d\u6267\u884c\u5206\u652f\u3002\\n\\n### \u5de5\u5177\u9694\u79bb\u4e0e\u5b89\u5168\u9650\u5236\\n\\n\u5b50 Agent \u7684\u9ed8\u8ba4\u9ed1\u540d\u5355\u5305\u62ec\uff1a\\n\\n```text\\ndelegate_task\\nclarify\\nmemory\\nsend_message\\nexecute_code\\ncronjob\\n```\\n\\n\u5b9a\u4e49\u5728 `tools/delegate_tool.py:44`\u3002\u8fd9\u610f\u5473\u7740 leaf subagent \u4e0d\u80fd\u7ee7\u7eed\u9012\u5f52\u751f\u5b50\u3001\u4e0d\u80fd\u5411\u7528\u6237\u53d1\u8d77\u6f84\u6e05\u3001\u4e0d\u80fd\u5199\u5171\u4eab memory\u3001\u4e0d\u80fd\u8de8\u5e73\u53f0\u53d1\u6d88\u606f\u3001\u4e0d\u80fd\u81ea\u5df1\u521b\u5efa cron job\u3002\\n\\n`role=\\"orchestrator\\"` \u53ef\u4ee5\u8ba9\u5b50 Agent \u4fdd\u7559 delegation \u80fd\u529b\uff0c\u4f46\u8981\u53d7 `delegation.max_spawn_depth` \u4e0e `delegation.orchestrator_enabled` \u7ea6\u675f\u3002\u9ed8\u8ba4 `max_spawn_depth=1`\uff0c\u6240\u4ee5\u9ed8\u8ba4\u662f\u6241\u5e73\u7ed3\u6784\uff1a\u7236 Agent \u53ef\u4ee5\u5f00\u5b50 Agent\uff0c\u5b50 Agent \u4e0d\u80fd\u518d\u5f00\u5b59 Agent\u3002\u6df1\u5ea6\u63a7\u5236\u5728 `tools/delegate_tool.py:467`\u3002\\n\\n### \u5e76\u884c\u3001\u9650\u6d41\u4e0e\u5f02\u6b65\u56de\u6d41\\n\\n`delegation.max_concurrent_children` \u63a7\u5236\u4e00\u6b21 fan-out \u7684\u6700\u5927\u5e76\u884c\u5b50 Agent \u6570\uff0c\u9ed8\u8ba4\u662f 3\uff0c\u89c1 `tools/delegate_tool.py:354`\u3002\\n\\n\u6279\u91cf\u4efb\u52a1\u4f1a\u901a\u8fc7 daemon thread pool \u5e76\u884c\u8fd0\u884c\uff0c\u6838\u5fc3\u903b\u8f91\u5728 `tools/delegate_tool.py:2457` \u5230 `tools/delegate_tool.py:2680`\u3002\u9876\u5c42 Agent \u8c03\u7528 `delegate_task` \u65f6\uff0c`run_agent.py:_dispatch_delegate_task` \u4f1a\u5f3a\u5236 background\uff1a\u7236\u4f1a\u8bdd\u4e0d\u963b\u585e\uff0c\u5b50 Agent \u5b8c\u6210\u540e\u7ed3\u679c\u4f5c\u4e3a\u65b0\u7684 completion event \u56de\u5230\u539f\u4f1a\u8bdd\uff0c\u89c1 `run_agent.py:5696`\u3002\\n\\n\u5f02\u6b65 registry \u5728 `tools/async_delegation.py`\u3002\u5b83\u4f1a\u628a dispatch \u548c completion \u8bb0\u5f55\u5230\u5f53\u524d profile \u7684 `state.db`\uff0c\u5e76\u901a\u8fc7\u5171\u4eab completion queue \u628a\u7ed3\u679c\u9001\u56de CLI / gateway drain loop\uff0c\u89c1 `tools/async_delegation.py:1`\u3001`tools/async_delegation.py:425` \u548c `tools/async_delegation.py:632`\u3002\\n\\n### \u9002\u5408\u548c\u4e0d\u9002\u5408\u7684\u573a\u666f\\n\\n`delegate_task` \u9002\u5408\uff1a\\n\\n- \u5e76\u884c\u9605\u8bfb\u51e0\u4e2a\u72ec\u7acb\u6587\u4ef6\uff1b\\n- \u8ba9\u4e24\u4e2a\u5b50 Agent \u5206\u522b\u8c03\u7814 A/B \u65b9\u6848\uff1b\\n- \u8ba9\u5b50 Agent \u505a\u4ee3\u7801 review\u3001\u8d44\u6599\u6458\u5f55\u3001\u5c40\u90e8\u9a8c\u8bc1\uff1b\\n- \u7236 Agent \u9700\u8981\u4e00\u4e2a\u77ed summary \u624d\u80fd\u7ee7\u7eed\u63a8\u7406\u3002\\n\\n\u5b83\u4e0d\u9002\u5408\uff1a\\n\\n- \u9700\u8981\u8de8\u5929\u7ee7\u7eed\u7684\u5de5\u4f5c\uff1b\\n- \u9700\u8981\u957f\u671f\u8eab\u4efd\u3001\u957f\u671f\u8bb0\u5fc6\u3001\u957f\u671f\u6280\u80fd\u6f14\u5316\u7684 Agent\uff1b\\n- \u9700\u8981\u4eba\u7c7b\u4e2d\u9014\u8bc4\u8bba\u3001block/unblock\u3001\u5ba1\u8ba1 trail \u7684\u6d41\u7a0b\uff1b\\n- \u9700\u8981\u4e0d\u540c profile \u5404\u81ea\u5e26\u4e0d\u540c `SOUL.md` \u4e0e `.env` \u7684\u5de5\u4f5c\u3002\\n\\n\u8fd9\u4e9b\u5e94\u8be5\u4ea4\u7ed9 Kanban + Profile\u3002\\n\\n## Kanban\uff1a\u628a profile \u5f53\u6210\u957f\u671f worker \u8c03\u5ea6\\n\\nKanban \u662f Hermes \u91cc\u6700\u50cf\u201c\u591a Agent \u534f\u4f5c\u7cfb\u7edf\u201d\u7684\u673a\u5236\u3002\u6587\u6863\u628a\u5b83\u5b9a\u4e49\u4e3a\u4e00\u4e2a SQLite-backed durable task board\uff1a\u6240\u6709 profile \u5171\u4eab\u540c\u4e00\u4e2a board\uff0c\u6bcf\u4e2a task \u6709 assignee\uff0c\u6bcf\u4e2a worker \u662f\u5b8c\u6574 OS process\uff0c\u5e26\u81ea\u5df1\u7684 identity\u3002\u89c1 `website/docs/user-guide/features/kanban.md:7`\u3002\\n\\n\u5b98\u65b9\u6587\u6863\u4e5f\u660e\u786e\u6bd4\u8f83\u4e86 Kanban \u548c `delegate_task`\uff1a\\n\\n| \u7ef4\u5ea6 | `delegate_task` | Kanban |\\n| --- | --- | --- |\\n| \u5f62\u6001 | RPC / fork-join | Durable queue + state machine |\\n| \u5b50 Agent | \u533f\u540d subagent | named profile worker |\\n| \u8bb0\u5fc6 | \u9ed8\u8ba4\u65e0\u957f\u671f\u8bb0\u5fc6 | \u4f7f\u7528 assignee profile \u7684\u957f\u671f\u8bb0\u5fc6 |\\n| \u6062\u590d | \u4e0d\u53ef\u6062\u590d | \u53ef block\u3001unblock\u3001retry\u3001reclaim |\\n| \u5ba1\u8ba1 | summary \u56de\u6d41 | SQLite events / comments / runs |\\n| \u4eba\u7c7b\u4ecb\u5165 | \u4e0d\u652f\u6301 | \u53ef\u4ee5\u8bc4\u8bba\u3001\u963b\u585e\u3001\u89e3\u963b\u585e |\\n\\n\u5bf9\u5e94\u8bf4\u660e\u5728 `website/docs/user-guide/features/kanban.md:32`\u3002\\n\\n### dispatcher \u5982\u4f55 spawn worker\\n\\nKanban dispatcher \u4f1a\u626b\u63cf ready tasks\uff0c\u68c0\u67e5 assignee \u662f\u5426\u662f\u4e00\u4e2a\u771f\u5b9e Hermes profile\uff0c\u7136\u540e claim \u4efb\u52a1\u5e76\u8c03\u7528 `_default_spawn()`\u3002\u8c03\u5ea6\u4e3b\u903b\u8f91\u5728 `hermes_cli/kanban_db.py:7240`\u3002\\n\\n`_default_spawn()` \u7684\u6838\u5fc3\u52a8\u4f5c\u662f\u542f\u52a8\u4e00\u4e2a\u5b50\u8fdb\u7a0b\uff1a\\n\\n```text\\nhermes -p <assignee> --cli --accept-hooks chat -q \\"work kanban task <task_id>\\"\\n```\\n\\n\u6e90\u7801\u5165\u53e3\u5728 `hermes_cli/kanban_db.py:7904`\u3002\u5b83\u4f1a\u7ed9 worker \u6ce8\u5165\u4e00\u7ec4\u73af\u5883\u53d8\u91cf\uff1a\\n\\n| \u53d8\u91cf | \u542b\u4e49 |\\n| --- | --- |\\n| `HERMES_HOME` | assignee profile \u7684 home\uff0c\u8ba9 worker \u8bfb\u53d6\u81ea\u5df1\u7684\u914d\u7f6e\u3001\u8bb0\u5fc6\u548c skills |\\n| `HERMES_PROFILE` | worker \u7684 profile \u540d\uff0c\u7528\u4e8e\u8bc4\u8bba\u7f72\u540d |\\n| `HERMES_KANBAN_TASK` | \u5f53\u524d\u4efb\u52a1 id |\\n| `HERMES_KANBAN_WORKSPACE` | \u5f53\u524d\u4efb\u52a1 workspace |\\n| `HERMES_KANBAN_DB` | \u5f53\u524d board \u7684 SQLite \u8def\u5f84 |\\n| `HERMES_KANBAN_BOARD` | \u5f53\u524d board slug |\\n| `HERMES_KANBAN_WORKSPACES_ROOT` | \u5f53\u524d board \u7684 workspace root |\\n| `TERMINAL_CWD` | pin \u5230\u4efb\u52a1 workspace |\\n\\n`HERMES_HOME` \u6ce8\u5165\u903b\u8f91\u5728 `hermes_cli/kanban_db.py:7933`\uff0cboard / workspace pinning \u5728 `hermes_cli/kanban_db.py:7994`\uff0c\u6700\u7ec8 `subprocess.Popen` \u5728 `hermes_cli/kanban_db.py:8069`\u3002\\n\\n\u8fd9\u610f\u5473\u7740 Kanban worker \u4e0d\u662f\u533f\u540d\u5b50 Agent\uff0c\u800c\u662f\u4e00\u4e2a\u5b8c\u6574 profile\uff1a\u5b83\u4f1a\u4f7f\u7528 assignee profile \u7684 `SOUL.md`\u3001memory\u3001skills\u3001model\u3001toolsets\u3001secrets \u548c terminal backend\u3002\\n\\n### worker \u534f\u8bae\\n\\n\u6bcf\u4e2a Kanban worker \u7684\u7cfb\u7edf\u63d0\u793a\u90fd\u4f1a\u6ce8\u5165 `KANBAN_GUIDANCE`\uff1a\\n\\n1. \u5148\u8c03\u7528 `kanban_show()` \u8bfb\u4efb\u52a1\u3001\u7236\u4efb\u52a1 handoff\u3001\u5386\u53f2\u5c1d\u8bd5\u548c\u8bc4\u8bba\uff1b\\n2. \u8fdb\u5165 `$HERMES_KANBAN_WORKSPACE` \u5de5\u4f5c\uff1b\\n3. \u957f\u4efb\u52a1\u5b9a\u671f `kanban_heartbeat()`\uff1b\\n4. \u5b8c\u6210\u65f6 `kanban_complete()`\uff1b\u5361\u4f4f\u65f6 `kanban_block()`\u3002\\n\\n\u6587\u6863\u8bf4\u660e\u89c1 `website/docs/user-guide/features/kanban.md:361`\u3002\\n\\n\u5982\u679c worker \u8fdb\u7a0b\u6b63\u5e38\u9000\u51fa\u4f46\u4efb\u52a1\u4ecd\u662f running\uff0cdispatcher \u4f1a\u8ba4\u4e3a\u8fd9\u662f protocol violation\uff0c\u800c\u4e0d\u662f\u76f4\u63a5\u628a\u4efb\u52a1\u5f53\u5b8c\u6210\u3002\u8fd9\u6837\u4efb\u52a1\u72b6\u6001\u4e0d\u4f1a\u53ea\u9760\u6587\u672c\u8f93\u51fa\u6f02\u79fb\uff0c\u800c\u662f\u5fc5\u987b\u901a\u8fc7 `kanban_*` \u5de5\u5177\u843d\u5e93\u3002\\n\\n### orchestrator profile\\n\\nKanban \u8fd8\u652f\u6301 orchestrator \u6a21\u5f0f\uff1a\u4e00\u4e2a profile \u4e0d\u81ea\u5df1\u505a\u5b9e\u73b0\uff0c\u800c\u662f\u628a\u9ad8\u5c42\u76ee\u6807\u62c6\u6210\u591a\u4e2a\u5b50\u4efb\u52a1\uff0c\u5206\u914d\u7ed9 researcher\u3001coder\u3001writer\u3001reviewer \u7b49 specialist profile\u3002\\n\\n\u6587\u6863\u91cc\u7684\u63a8\u8350\u505a\u6cd5\u662f\uff1aorchestrator profile \u53ea\u5f00 `kanban` / gateway / memory \u7b49\u63a7\u5236\u9762\u5de5\u5177\uff0c\u5173\u95ed terminal / file / code / web \u8fd9\u7c7b\u5b9e\u73b0\u5de5\u5177\uff0c\u907f\u514d\u5b83\u201c\u5fcd\u4e0d\u4f4f\u81ea\u5df1\u5e72\u6d3b\u201d\uff0c\u89c1 `website/docs/user-guide/features/kanban.md:430`\u3002\\n\\n## Gateway multiplex\uff1a\u4e00\u4e2a\u5165\u53e3\u670d\u52a1\u591a\u4e2a profile\\n\\n\u9ed8\u8ba4\u60c5\u51b5\u4e0b\uff0c\u6bcf\u4e2a profile \u53ef\u4ee5\u8dd1\u81ea\u5df1\u7684 gateway\uff1a\\n\\n```bash\\ncoder gateway start\\nwriter gateway start\\nresearcher gateway start\\n```\\n\\n\u8fd9\u662f\u4e00 profile \u4e00\u8fdb\u7a0b\uff0c\u9694\u79bb\u6700\u6e05\u6670\u3002\u6587\u6863\u5728 `website/docs/user-guide/multi-profile-gateways.md:5`\u3002\\n\\n\u53e6\u4e00\u79cd\u6a21\u5f0f\u662f multiplex\uff1adefault gateway \u4f5c\u4e3a\u552f\u4e00\u5165\u53e3\u8fdb\u7a0b\uff0c\u540c\u65f6\u670d\u52a1\u673a\u5668\u4e0a\u7684\u591a\u4e2a profile\u3002\u5f00\u542f\u65b9\u5f0f\uff1a\\n\\n```bash\\nhermes config set gateway.multiplex_profiles true\\nhermes gateway restart\\n```\\n\\n\u6587\u6863\u8bf4\u660e\u89c1 `website/docs/user-guide/multi-profile-gateways.md:59`\u3002\\n\\nmultiplex \u7684\u5173\u952e\u4e0d\u662f\u201c\u628a\u6240\u6709 profile \u914d\u7f6e\u6df7\u8fdb\u4e00\u4e2a\u8fdb\u7a0b\u201d\uff0c\u800c\u662f\u6bcf\u4e2a turn \u52a8\u6001\u5207 profile scope\uff1a\\n\\n```mermaid\\nsequenceDiagram\\n  participant Msg as Inbound message\\n  participant Mux as Default gateway multiplexer\\n  participant Scope as Profile runtime scope\\n  participant Agent as AIAgent turn\\n\\n  Msg->>Mux: profile=researcher\\n  Mux->>Scope: set_hermes_home_override(researcher home)\\n  Mux->>Scope: set_secret_scope(researcher .env)\\n  Scope->>Agent: load config / SOUL / memory / skills / provider keys\\n  Agent--\x3e>Msg: response via researcher adapter/session\\n  Scope->>Scope: reset contextvars\\n```\\n\\n\u540c\u65f6\uff0cgateway session key \u4f1a\u6309 profile namespace \u9694\u79bb\u3002\u9ed8\u8ba4 profile \u7ee7\u7eed\u7528\u5386\u53f2\u517c\u5bb9\u7684 `agent:main`\uff0cnamed profile \u7528 `agent:<profile>`\uff0c\u8fd9\u6837\u540c\u4e00\u4e2a\u5e73\u53f0\u3001\u540c\u4e00\u4e2a chat \u5728\u4e0d\u540c profile \u4e0b\u4e0d\u4f1a\u649e session\u3002\u5b9e\u73b0\u89c1 `gateway/session.py:851` \u548c `gateway/session.py:1300`\u3002\\n\\n## \u591a\u673a\u5668\uff1a\u9760\u6267\u884c backend\uff0c\u4e0d\u9760 profile \u540d\u5b57\u672c\u8eab\\n\\nProfile \u4e0d\u662f sandbox\uff0c\u4e5f\u4e0d\u662f\u673a\u5668\u3002\u5b83\u53ea\u662f Hermes \u72b6\u6001\u76ee\u5f55\u9694\u79bb\u3002\u7528\u6237\u6587\u6863\u7279\u522b\u63d0\u9192\uff1aprofile \u548c workspace / sandbox \u662f\u4e0d\u540c\u6982\u5ff5\uff1blocal backend \u4e0b\uff0cagent \u4ecd\u7136\u6709\u540c\u4e00\u4e2a OS \u7528\u6237\u80fd\u8bbf\u95ee\u7684\u6587\u4ef6\u6743\u9650\uff0c\u89c1 `website/docs/user-guide/profiles.md:125`\u3002\\n\\n\u5982\u679c\u8981\u8ba9 Agent \u5230\u4e0d\u540c\u673a\u5668\u6216\u4e0d\u540c\u9694\u79bb\u73af\u5883\u5de5\u4f5c\uff0c\u8981\u914d\u7f6e terminal backend\u3002\\n\\n\u6587\u6863\u5217\u51fa\u7684 backend \u5305\u62ec\uff1a\\n\\n| Backend | \u4f5c\u7528 |\\n| --- | --- |\\n| `local` | \u5728\u5f53\u524d\u673a\u5668\u6267\u884c\uff0c\u9ed8\u8ba4\u65b9\u5f0f |\\n| `docker` | \u5bb9\u5668\u9694\u79bb\uff0c\u9002\u5408\u5b89\u5168\u548c\u590d\u73b0 |\\n| `ssh` | \u8fdc\u7aef\u673a\u5668\uff0c\u9002\u5408\u628a Agent \u6267\u884c\u9762\u653e\u5230\u670d\u52a1\u5668 |\\n| `singularity` | HPC / rootless container \u573a\u666f |\\n| `modal` | serverless cloud \u6267\u884c |\\n| `daytona` | cloud sandbox workspace |\\n\\n\u89c1 `website/docs/user-guide/features/tools.md:56`\u3002\\n\\nProfile \u7ea7\u914d\u7f6e\u793a\u4f8b\uff1a\\n\\n```yaml\\nterminal:\\n  backend: ssh\\n  cwd: /absolute/path/to/project\\n```\\n\\n\u8fd9\u4f1a\u8ba9\u8be5 profile \u7684 terminal / file / code execution \u9ed8\u8ba4\u8d70 SSH backend\u3002\\n\\n\u53e6\u5916\uff0cgateway session \u4e5f\u53ef\u4ee5\u4e34\u65f6\u8fdb\u5165 SSH Mode\u3002`tools/ssh_mode_tool.py` \u63d0\u4f9b\u6a21\u578b\u53ef\u89c1\u63a7\u5236\u9762\uff1a\\n\\n- `ssh_mode.status`\uff1a\u67e5\u770b\u5f53\u524d session \u662f\u5426\u5728 SSH\uff1b\\n- `ssh_mode.list_targets`\uff1a\u5217\u51fa Hermes \u7ba1\u7406\u7684 SSH targets\uff1b\\n- `ssh_mode.request_use`\uff1a\u5728\u6388\u6743\u540e\u5207\u5165 SSH\uff1b\\n- `ssh_mode.request_local`\uff1a\u9000\u51fa\u6a21\u578b\u521b\u5efa\u7684 SSH binding\u3002\\n\\n\u5bf9\u5e94\u5b9e\u73b0\u89c1 `tools/ssh_mode_tool.py:144`\u3001`tools/ssh_mode_tool.py:170` \u548c `tools/ssh_mode_tool.py:262`\u3002\\n\\n### \u4efb\u52a1\u6267\u884c\u9762\u548c\u63a7\u5236\u9762\u8981\u5206\u5f00\\n\\nSSH / Docker / Modal \u5f71\u54cd\u7684\u662f\u4efb\u52a1\u6267\u884c\u9762\uff1a\\n\\n- `terminal`\\n- file tools\\n- `execute_code`\\n\\n\u4f46 Hermes \u63a7\u5236\u9762\u4ecd\u5c5e\u4e8e\u672c\u5730 profile\uff1a\\n\\n- skills\\n- memory\\n- cron\\n- session database\\n- gateway status\\n- profile config\\n\\n\u8fd9\u4e5f\u662f\u4e3a\u4ec0\u4e48\u201c\u8fdc\u7aef\u673a\u5668\u201d\u4e0d\u7b49\u4e8e\u201c\u8fdc\u7aef Hermes profile\u201d\u3002\u5982\u679c\u76ee\u6807\u662f\u7ef4\u62a4\u8fdc\u7aef\u90a3\u5957 Hermes\uff0c\u9700\u8981\u5728\u90a3\u91cc\u5355\u72ec\u90e8\u7f72 Hermes\uff1b\u5982\u679c\u53ea\u662f\u8ba9\u672c\u5730 profile \u5728\u8fdc\u7aef\u5de5\u4f5c\u533a\u6267\u884c\u547d\u4ee4\uff0c\u914d\u7f6e terminal backend \u5373\u53ef\u3002\\n\\n## \u4e09\u79cd\u5178\u578b\u7ec4\u5408\\n\\n### 1. \u4e00\u6b21\u6027\u5e76\u884c\u8c03\u7814\\n\\n```text\\n\u7528\u6237\u95ee\u9898 -> \u7236 Agent -> delegate_task(A/B/C) -> \u5b50 Agent summaries -> \u7236 Agent \u603b\u7ed3\\n```\\n\\n\u9002\u5408\u77ed\u5e73\u5feb\uff0c\u4e0d\u9700\u8981\u957f\u671f\u8bb0\u5fc6\u3002\\n\\n### 2. \u957f\u671f\u89d2\u8272\u534f\u4f5c\\n\\n```bash\\nhermes profile create researcher --description \\"Searches docs, code, and web sources.\\"\\nhermes profile create writer --description \\"Writes polished Chinese technical posts.\\"\\nhermes profile create reviewer --description \\"Reviews claims, risks, and missing tests.\\"\\n\\nhermes kanban init\\nhermes gateway start\\nhermes kanban create \\"\u6574\u7406\u67d0\u4e2a\u7cfb\u7edf\u7684\u516c\u5f00\u6280\u672f\u6587\u7ae0\\" --assignee researcher\\n```\\n\\n\u63a5\u4e0b\u6765\u53ef\u4ee5\u8ba9 researcher \u5b8c\u6210\u8d44\u6599\u3001writer \u63a5 synthesis\u3001reviewer \u505a\u4e8b\u5b9e\u6821\u9a8c\u3002\u6bcf\u4e2a worker \u90fd\u662f\u81ea\u5df1\u7684 profile\u3002\\n\\n### 3. \u591a\u73af\u5883\u6267\u884c\\n\\n```bash\\nhermes profile create remote-coder --description \\"Implements code on a remote staging host.\\"\\nremote-coder config set terminal.backend ssh\\nremote-coder config set terminal.cwd /srv/project\\n```\\n\\n`remote-coder` \u7684\u8eab\u4efd\u3001\u8bb0\u5fc6\u3001skills \u5728\u672c\u5730 profile\uff1b\u5b83\u7684\u6267\u884c\u9762\u8d70\u8fdc\u7aef SSH\u3002\u9700\u8981\u66f4\u5f3a\u9694\u79bb\u65f6\uff0c\u7528 Docker / Modal / Daytona\u3002\\n\\n## \u8fb9\u754c\u4e0e\u98ce\u9669\\n\\n:::warning Profile \u4e0d\u662f\u5b89\u5168\u6c99\u7bb1\\nProfile \u9694\u79bb\u7684\u662f Hermes \u5e94\u7528\u72b6\u6001\uff0c\u4e0d\u662f OS \u6743\u9650\u3002local backend \u4e0b\uff0c\u540c\u4e00 Unix \u7528\u6237\u80fd\u8bfb\u5199\u7684\u8def\u5f84\uff0cprofile \u901a\u5e38\u4e5f\u80fd\u8bbf\u95ee\u3002\u5f3a\u9694\u79bb\u9700\u8981\u5bb9\u5668\u3001SSH \u5230\u72ec\u7acb\u673a\u5668\u3001\u4e91 sandbox \u6216 OS \u7ea7\u6743\u9650\u9694\u79bb\u3002\\n:::\\n\\n\u9700\u8981\u7279\u522b\u6ce8\u610f\uff1a\\n\\n1. **secrets \u4e0d\u80fd\u5168\u5c40\u6df7\u7528\u3002** multiplex \u6a21\u5f0f\u4e0b\u5e94\u8be5\u901a\u8fc7 `get_secret()` \u4e0e secret scope \u8bfb\u53d6\u5bc6\u94a5\uff0c\u907f\u514d\u76f4\u63a5\u8bfb `os.environ` \u9020\u6210\u8de8 profile \u6cc4\u6f0f\u3002\\n2. **\u4fee\u6539 `SOUL.md` / skills / memory \u4e0d\u4e00\u5b9a\u5f71\u54cd\u5f53\u524d session\u3002** \u5f88\u591a prompt \u5185\u5bb9\u5728 session \u5f00\u59cb\u6216 prompt cache \u4e2d\u56fa\u5b9a\uff1b\u4fee\u6539\u540e\u6700\u597d\u5f00\u65b0 session\u3002\\n3. **`delegate_task` \u7684\u7ed3\u679c\u662f self-report\u3002** \u7236 Agent \u5e94\u9a8c\u8bc1\u5b50 Agent \u58f0\u79f0\u5199\u5165\u7684\u6587\u4ef6\u3001URL \u6216\u5916\u90e8\u526f\u4f5c\u7528\u3002\\n4. **Kanban board \u662f\u5171\u4eab\u534f\u4f5c\u9762\u3002** comments\u3001metadata\u3001task bodies \u4e0d\u5e94\u8be5\u5199\u5165 token\u3001\u79c1\u5bc6\u8def\u5f84\u6216\u4e0d\u53ef\u516c\u5f00\u4fe1\u606f\u3002\\n5. **clone profile \u4f1a\u590d\u5236\u8eab\u4efd\u4e0e\u5bc6\u94a5\u3002** `--clone` / `--clone-all` \u5f88\u65b9\u4fbf\uff0c\u4f46\u590d\u5236 `.env` \u524d\u8981\u786e\u8ba4\u662f\u5426\u771f\u7684\u5e0c\u671b\u4e24\u4e2a profile \u4f7f\u7528\u540c\u4e00\u6279\u51ed\u636e\u3002\\n6. **\u591a\u673a\u5668\u4e0d\u662f\u81ea\u52a8\u5206\u5e03\u5f0f\u3002** Hermes \u9ed8\u8ba4\u662f\u5355\u673a profile + \u5355\u673a SQLite board\uff1b\u8de8\u673a\u5668 fleet \u9700\u8981\u989d\u5916\u90e8\u7f72\u3001\u5171\u4eab\u5b58\u50a8\u6216\u5916\u90e8 lane \u8bbe\u8ba1\u3002\\n\\n## \u63a8\u8350\u5fc3\u667a\u6a21\u578b\\n\\n\u6700\u540e\u53ef\u4ee5\u7528\u8fd9\u56db\u53e5\u8bdd\u8bb0\u4f4f Hermes \u7684 Multi-Agent \u8bbe\u8ba1\uff1a\\n\\n```text\\nProfile       = \u957f\u671f\u8eab\u4efd\u3001\u4eba\u683c\u3001\u8bb0\u5fc6\u3001\u914d\u7f6e\u3001\u5bc6\u94a5\u3001\u6280\u80fd\\nSubagent      = \u4e00\u6b21\u4efb\u52a1\u91cc\u7684\u533f\u540d\u4e34\u65f6\u5e76\u884c\u5206\u652f\\nKanban        = \u591a\u4e2a\u957f\u671f profile \u4e4b\u95f4\u7684 durable work queue\\nTerminal backend = \u628a\u67d0\u4e2a profile/session \u7684\u6267\u884c\u9762\u653e\u5230\u672c\u5730\u3001\u5bb9\u5668\u3001\u8fdc\u7aef\u6216\u4e91\\n```\\n\\n\u56e0\u6b64\uff0cHermes \u786e\u5b9e\u80fd\u505a\u5230\u201c\u4e0d\u540c\u4e2a\u6027\u3001\u4e0d\u540c\u8bb0\u5fc6\u3001\u4e0d\u540c\u673a\u5668\u534f\u4f5c\u201d\uff0c\u4f46\u6b63\u786e\u7ec4\u5408\u662f\uff1a\\n\\n- \u4e0d\u540c\u4e2a\u6027 / \u8bb0\u5fc6\uff1a\u521b\u5efa\u4e0d\u540c Profile\uff1b\\n- \u591a\u89d2\u8272\u957f\u671f\u534f\u4f5c\uff1a\u7528 Kanban \u628a\u4efb\u52a1\u5206\u914d\u7ed9\u4e0d\u540c profile\uff1b\\n- \u4e34\u65f6\u5e76\u884c\u63a2\u7d22\uff1a\u7528 `delegate_task`\uff1b\\n- \u4e0d\u540c\u673a\u5668\u6267\u884c\uff1a\u7ed9 profile \u6216 session \u914d SSH / Docker / Modal / Daytona\uff1b\\n- \u4e00\u4e2a\u5165\u53e3\u670d\u52a1\u591a\u4e2a profile\uff1a\u5728\u786e\u8ba4 secret \u8def\u5f84\u5b89\u5168\u540e\u5f00\u542f Gateway multiplex\u3002\\n\\n\u8fd9\u5957\u8bbe\u8ba1\u7684\u4f18\u70b9\u662f\u8fb9\u754c\u6e05\u6670\uff1a\u957f\u671f\u8eab\u4efd\u3001\u4e34\u65f6\u5e76\u884c\u3001\u6301\u4e45\u8c03\u5ea6\u3001\u5165\u53e3\u8def\u7531\u3001\u6267\u884c\u73af\u5883\u5404\u81ea\u72ec\u7acb\uff0c\u53ef\u4ee5\u6309\u4efb\u52a1\u590d\u6742\u5ea6\u9010\u5c42\u542f\u7528\uff0c\u800c\u4e0d\u662f\u628a\u6240\u6709\u201c\u591a Agent\u201d\u573a\u666f\u90fd\u585e\u8fdb\u4e00\u4e2a\u673a\u5236\u91cc\u3002"},{"id":"hello-world-writing-public-notes-with-chatblog","metadata":{"permalink":"/ChatBlog/dev/blog/hello-world-writing-public-notes-with-chatblog","editUrl":"https://github.com/ChatArch/ChatBlog/tree/main/blog/2026-06-29-hello-world.mdx","source":"@site/blog/2026-06-29-hello-world.mdx","title":"Hello World\uff1aChatBlog \u6846\u67b6\u80fd\u529b\u5c55\u793a","description":"\u7b2c\u4e00\u7bc7 ChatBlog \u535a\u5ba2\uff0c\u7528\u6765\u5c55\u793a\u5f53\u524d\u535a\u5ba2\u6846\u67b6\u53ef\u4ee5\u652f\u6301\u7684\u56fe\u793a\u3001\u63d0\u793a\u6846\u3001Tabs\u3001\u4ee3\u7801\u5757\u3001\u6298\u53e0\u5185\u5bb9\u7b49\u5199\u4f5c\u80fd\u529b\u3002","date":"2026-06-29T00:00:00.000Z","tags":[{"inline":true,"label":"chatblog","permalink":"/ChatBlog/dev/blog/tags/chatblog"},{"inline":true,"label":"public","permalink":"/ChatBlog/dev/blog/tags/public"},{"inline":true,"label":"writing","permalink":"/ChatBlog/dev/blog/tags/writing"},{"inline":true,"label":"mermaid","permalink":"/ChatBlog/dev/blog/tags/mermaid"},{"inline":true,"label":"mdx","permalink":"/ChatBlog/dev/blog/tags/mdx"}],"readingTime":3.2,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Hello World\uff1aChatBlog \u6846\u67b6\u80fd\u529b\u5c55\u793a","date":"2026-06-29T00:00:00.000Z","slug":"hello-world-writing-public-notes-with-chatblog","tags":["chatblog","public","writing","mermaid","mdx"],"description":"\u7b2c\u4e00\u7bc7 ChatBlog \u535a\u5ba2\uff0c\u7528\u6765\u5c55\u793a\u5f53\u524d\u535a\u5ba2\u6846\u67b6\u53ef\u4ee5\u652f\u6301\u7684\u56fe\u793a\u3001\u63d0\u793a\u6846\u3001Tabs\u3001\u4ee3\u7801\u5757\u3001\u6298\u53e0\u5185\u5bb9\u7b49\u5199\u4f5c\u80fd\u529b\u3002"},"unlisted":false,"prevItem":{"title":"Hermes Multi-Agent\uff1aProfile\u3001Subagent \u4e0e Kanban \u7684\u4e09\u5c42\u534f\u4f5c\u6a21\u578b","permalink":"/ChatBlog/dev/blog/hermes-multi-agent-profile-subagent-kanban"},"nextItem":{"title":"Hermes SSH Mode\uff1a\u8ba9\u6a21\u578b\u5b89\u5168\u5730\u8fdb\u5165\u8fdc\u7aef\u5de5\u4f5c\u533a","permalink":"/ChatBlog/dev/blog/hermes-ssh-mode-model-controlled-remote-workspace"}},"content":"import Tabs from \'@theme/Tabs\';\\nimport TabItem from \'@theme/TabItem\';\\n\\n\\n\u8fd9\u7bc7\u6587\u7ae0\u662f ChatBlog \u7684\u7b2c\u4e00\u7bc7\u535a\u5ba2\uff0c\u4e5f\u662f\u5f53\u524d\u535a\u5ba2\u6846\u67b6\u7684\u80fd\u529b\u5c55\u793a\u9875\u3002\\n\\n\u5b83\u7684\u76ee\u7684\u4e0d\u662f\u5199\u4e00\u7bc7\u666e\u901a\u7684 hello world\uff0c\u800c\u662f\u5148\u8ba9\u6211\u4eec\u611f\u53d7\u4e00\u4e0b\uff1a\u8fd9\u4e2a\u516c\u5f00\u535a\u5ba2\u7ad9\u70b9\u9664\u4e86\u5e38\u89c4 Markdown \u6587\u7ae0\u4e4b\u5916\uff0c\u8fd8\u80fd\u627f\u8f7d\u54ea\u4e9b\u66f4\u4e30\u5bcc\u7684\u6280\u672f\u8868\u8fbe\u5f62\u5f0f\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n:::tip \u5f53\u524d\u7ed3\u8bba\\nChatBlog \u5f53\u524d\u57fa\u4e8e Docusaurus \u642d\u5efa\uff0c\u9ed8\u8ba4\u4e2d\u6587\uff0c\u652f\u6301 Markdown / MDX\u3001Mermaid \u56fe\u793a\u3001\u63d0\u793a\u6846\u3001Tabs\u3001\u6298\u53e0\u5185\u5bb9\u3001\u4ee3\u7801\u5757\u3001\u8868\u683c\uff0c\u4ee5\u53ca\u540e\u7eed\u81ea\u5b9a\u4e49 React \u7ec4\u4ef6\u3002\\n:::\\n\\n## \u8fd9\u4e2a\u6846\u67b6\u9002\u5408\u505a\u4ec0\u4e48\\n\\nChatBlog \u9762\u5411\u516c\u5f00\u77e5\u8bc6\u4ea7\u51fa\uff1a\u628a ChatArch \u5de5\u4f5c\u4e2d\u53ef\u4ee5\u516c\u5f00\u7684\u6280\u672f\u53d1\u73b0\u3001\u8bbe\u8ba1\u89e3\u91ca\u548c\u5b9e\u73b0\u7b14\u8bb0\uff0c\u6574\u7406\u6210\u66f4\u5bb9\u6613\u9605\u8bfb\u3001\u5f15\u7528\u548c\u7ef4\u62a4\u7684\u6587\u7ae0\u4e0e\u77e5\u8bc6\u5757\u3002\\n\\n\u5b83\u9002\u5408\u627f\u8f7d\uff1a\\n\\n- \u6280\u672f\u535a\u5ba2\uff1a\u9636\u6bb5\u603b\u7ed3\u3001\u5b9e\u73b0\u8bb0\u5f55\u3001\u6392\u9519\u590d\u76d8\uff1b\\n- \u77e5\u8bc6\u5757\uff1a\u6bd4 Skill \u66f4\u8f7b\u3001\u66f4\u504f\u9605\u8bfb\u548c\u5f15\u7528\u7684\u7ed3\u6784\u5316\u77e5\u8bc6\uff1b\\n- \u67b6\u6784\u8bf4\u660e\uff1a\u6a21\u5757\u5173\u7cfb\u3001\u6d41\u7a0b\u56fe\u3001\u72b6\u6001\u673a\u3001\u65b9\u6848\u5bf9\u6bd4\uff1b\\n- \u9879\u76ee\u6587\u7ae0\uff1a\u53ef\u4ee5\u516c\u5f00\u7684\u9879\u76ee\u80cc\u666f\u3001\u8bbe\u8ba1\u53d6\u820d\u548c\u7ed3\u679c\u8bf4\u660e\u3002\\n\\n## \u4ece\u79c1\u6709\u5de5\u4f5c\u5230\u516c\u5f00\u5185\u5bb9\\n\\nChatBlog \u7684\u6838\u5fc3\u52a8\u4f5c\u4e0d\u662f\u201c\u590d\u5236\u804a\u5929\u8bb0\u5f55\u201d\uff0c\u800c\u662f\u201c\u628a\u53ef\u4ee5\u516c\u5f00\u7684\u77e5\u8bc6\u91cd\u65b0\u6574\u7406\u201d\u3002\\n\\n```mermaid\\nflowchart LR\\n  A[Playground \u79c1\u6709\u5de5\u4f5c] --\x3e B{\u662f\u5426\u9002\u5408\u516c\u5f00\uff1f}\\n  B --\x3e|\u5426| C[\u7559\u5728\u79c1\u6709 project / progress]\\n  B --\x3e|\u662f| D{\u5185\u5bb9\u5f62\u6001}\\n  D --\x3e|\u9636\u6bb5\u6027\u53d9\u8ff0| E[blog \u6280\u672f\u535a\u5ba2]\\n  D --\x3e|\u957f\u671f\u590d\u7528\u77e5\u8bc6| F[docs/blocks \u77e5\u8bc6\u5757]\\n  E --\x3e G[ChatBlog \u516c\u5f00\u7ad9\u70b9]\\n  F --\x3e G\\n```\\n\\n:::warning \u516c\u5f00\u8fb9\u754c\\n\u516c\u5f00\u5185\u5bb9\u4e0d\u5e94\u8be5\u5305\u542b\u79c1\u6709 token\u3001\u672a\u516c\u5f00\u7684\u9879\u76ee\u8fdb\u5ea6\u3001\u5185\u90e8\u670d\u52a1\u5730\u5740\u3001\u4e2a\u4eba\u9690\u79c1\u3001\u672a\u786e\u8ba4\u7684\u5546\u4e1a\u4fe1\u606f\u6216\u53ea\u80fd\u5728\u79c1\u6709 workspace \u4e2d\u6d41\u8f6c\u7684\u4e0a\u4e0b\u6587\u3002\\n:::\\n\\n## \u652f\u6301\u54ea\u4e9b\u5199\u4f5c\u80fd\u529b\\n\\n| \u80fd\u529b | \u7528\u9014 | \u9002\u5408\u573a\u666f |\\n| --- | --- | --- |\\n| Markdown | \u5e38\u89c4\u7ed3\u6784\u5316\u5199\u4f5c | \u6807\u9898\u3001\u5217\u8868\u3001\u8868\u683c\u3001\u94fe\u63a5\u3001\u5f15\u7528 |\\n| MDX | \u5728\u6587\u7ae0\u4e2d\u5d4c\u5165\u7ec4\u4ef6 | Tabs\u3001\u9879\u76ee\u5361\u7247\u3001\u540e\u7eed\u81ea\u5b9a\u4e49\u7ec4\u4ef6 |\\n| Mermaid | \u753b\u6d41\u7a0b\u56fe\u3001\u67b6\u6784\u56fe\u3001\u72b6\u6001\u673a | \u89e3\u91ca\u7cfb\u7edf\u6d41\u7a0b\u3001\u6a21\u5757\u5173\u7cfb |\\n| Admonition | \u63d0\u793a\u3001\u8b66\u544a\u3001\u7ed3\u8bba\u5148\u884c | \u98ce\u9669\u3001\u6ce8\u610f\u4e8b\u9879\u3001\u63a8\u8350\u65b9\u6848 |\\n| Details | \u6298\u53e0\u8865\u5145\u8bf4\u660e | \u7ec6\u8282\u8f83\u957f\u4f46\u4e0d\u662f\u4e3b\u7ebf |\\n| \u4ee3\u7801\u5757 | \u5c55\u793a\u547d\u4ee4\u3001\u914d\u7f6e\u3001\u793a\u4f8b | \u53ef\u590d\u5236\u64cd\u4f5c\u6216\u914d\u7f6e\u7247\u6bb5 |\\n\\n## \u540c\u4e00\u4e2a\u77e5\u8bc6\u70b9\u53ef\u4ee5\u6709\u4e0d\u540c\u5f62\u6001\\n\\n<Tabs>\\n  <TabItem value=\\"blog\\" label=\\"\u535a\u5ba2\\" default>\\n    \u9002\u5408\u8bb0\u5f55\u6709\u65f6\u95f4\u7ebf\u7684\u5185\u5bb9\uff1a\u4e00\u6b21\u5b9e\u73b0\u3001\u4e00\u6b21\u8c03\u7814\u3001\u4e00\u8f6e\u8bbe\u8ba1\u53d6\u820d\u3001\u4e00\u6b21\u6392\u9519\u590d\u76d8\u3002\u535a\u5ba2\u53ef\u4ee5\u6709\u80cc\u666f\u3001\u8fc7\u7a0b\u3001\u7ed3\u8bba\u548c\u540e\u7eed\u8ba1\u5212\u3002\\n  </TabItem>\\n  <TabItem value=\\"block\\" label=\\"\u77e5\u8bc6\u5757\\">\\n    \u9002\u5408\u6c89\u6dc0\u957f\u671f\u53ef\u590d\u7528\u7684\u77e5\u8bc6\uff1a\u4e00\u4e2a\u6982\u5ff5\u3001\u4e00\u79cd\u6a21\u5f0f\u3001\u4e00\u6bb5\u64cd\u4f5c\u89c4\u8303\u3001\u4e00\u4e2a\u67b6\u6784\u89e3\u91ca\u3002\u77e5\u8bc6\u5757\u5e94\u8be5\u77ed\u3001\u7a33\u3001\u65b9\u4fbf\u88ab\u5176\u4ed6\u6587\u7ae0\u5f15\u7528\u3002\\n  </TabItem>\\n  <TabItem value=\\"skill\\" label=\\"Skill\\">\\n    \u9002\u5408\u53ef\u6267\u884c\u7684\u6d41\u7a0b\uff1a\u5f53\u5185\u5bb9\u4e0d\u53ea\u662f\u89e3\u91ca\uff0c\u800c\u662f\u9700\u8981\u6a21\u578b\u53cd\u590d\u6309\u6b65\u9aa4\u64cd\u4f5c\u65f6\uff0c\u624d\u66f4\u9002\u5408\u505a\u6210 Skill\u3002\\n  </TabItem>\\n</Tabs>\\n\\n## \u5199\u4f5c\u6a21\u677f\u793a\u4f8b\\n\\n```md\\n---\\ntitle: \u6807\u9898\\ndate: 2026-06-29\\ntags: [chatblog, public]\\ndescription: \u4e00\u53e5\u8bdd\u6458\u8981\u3002\\n---\\n\\n# \u6807\u9898\\n\\n\u5148\u8bf4\u660e\u80cc\u666f\uff0c\u518d\u7ed9\u51fa\u7ed3\u8bba\u3002\\n\\n## \u5173\u952e\u70b9\\n\\n- \u7528\u7ed3\u6784\u7ec4\u7ec7\u5185\u5bb9\uff1b\\n- \u7528\u56fe\u793a\u89e3\u91ca\u6d41\u7a0b\uff1b\\n- \u7528\u4ee3\u7801\u5757\u4fdd\u7559\u53ef\u590d\u5236\u7247\u6bb5\uff1b\\n- \u7528\u63d0\u793a\u6846\u6807\u51fa\u98ce\u9669\u548c\u8fb9\u754c\u3002\\n```\\n\\n<details>\\n  <summary>\u4e3a\u4ec0\u4e48\u4e0d\u76f4\u63a5\u516c\u5f00\u539f\u59cb\u804a\u5929\u8bb0\u5f55\uff1f</summary>\\n\\n  \u539f\u59cb\u804a\u5929\u8bb0\u5f55\u901a\u5e38\u5305\u542b\u4e0a\u4e0b\u6587\u8df3\u8dc3\u3001\u4e34\u65f6\u5047\u8bbe\u3001\u79c1\u6709\u8def\u5f84\u3001\u672a\u6574\u7406\u7684\u4e2d\u95f4\u72b6\u6001\u3002\u516c\u5f00\u5185\u5bb9\u5e94\u8be5\u5148\u7ecf\u8fc7\u7b5b\u9009\u3001\u6539\u5199\u548c\u7ed3\u6784\u5316\uff0c\u8ba9\u8bfb\u8005\u80fd\u76f4\u63a5\u7406\u89e3\u5b83\u7684\u4ef7\u503c\u3002\\n</details>\\n\\n## \u540e\u7eed\u53ef\u4ee5\u7ee7\u7eed\u589e\u5f3a\u7684\u80fd\u529b\\n\\n\u7b2c\u4e00\u7248\u5148\u8bc1\u660e\u201c\u7ad9\u70b9\u80fd\u8dd1\u3001\u5185\u5bb9\u80fd\u5199\u3001\u7ed3\u6784\u80fd\u5c55\u793a\u201d\u3002\u540e\u7eed\u53ef\u4ee5\u7ee7\u7eed\u52a0\u5165\uff1a\\n\\n- \u81ea\u5b9a\u4e49\u9879\u76ee\u5361\u7247\uff1b\\n- \u6587\u7ae0\u4e0e\u77e5\u8bc6\u5757\u7684\u6765\u6e90\u94fe\u63a5\uff1b\\n- \u4e2d\u82f1\u6587\u591a\u8bed\u8a00\u7248\u672c\uff1b\\n- \u4ece Playground \u4e2d\u7b5b\u9009\u516c\u5f00\u5185\u5bb9\u7684\u540c\u6b65\u6d41\u7a0b\uff1b\\n- \u66f4\u590d\u6742\u7684\u56fe\u8868\u7ec4\u4ef6\u548c\u4ea4\u4e92\u5f0f\u793a\u4f8b\u3002"},{"id":"hermes-ssh-mode-model-controlled-remote-workspace","metadata":{"permalink":"/ChatBlog/dev/blog/hermes-ssh-mode-model-controlled-remote-workspace","editUrl":"https://github.com/ChatArch/ChatBlog/tree/main/blog/2026-06-29-hermes-ssh-mode.mdx","source":"@site/blog/2026-06-29-hermes-ssh-mode.mdx","title":"Hermes SSH Mode\uff1a\u8ba9\u6a21\u578b\u5b89\u5168\u5730\u8fdb\u5165\u8fdc\u7aef\u5de5\u4f5c\u533a","description":"\u89e3\u91ca Hermes SSH Mode \u7684\u673a\u5236\u3001\u7528\u6cd5\u3001\u5b89\u5168\u8fb9\u754c\uff0c\u4ee5\u53ca\u4e3a\u4ec0\u4e48\u6a21\u578b\u9700\u8981\u4e00\u4e2a\u53ef\u53d1\u73b0\u7684 ssh_mode \u5de5\u5177\u6765\u4e3b\u52a8\u8bf7\u6c42\u8fdb\u5165\u548c\u9000\u51fa\u8fdc\u7aef\u5de5\u4f5c\u533a\u3002","date":"2026-06-29T00:00:00.000Z","tags":[{"inline":true,"label":"hermes","permalink":"/ChatBlog/dev/blog/tags/hermes"},{"inline":true,"label":"ssh","permalink":"/ChatBlog/dev/blog/tags/ssh"},{"inline":true,"label":"agent","permalink":"/ChatBlog/dev/blog/tags/agent"},{"inline":true,"label":"feishu","permalink":"/ChatBlog/dev/blog/tags/feishu"},{"inline":true,"label":"remote-workspace","permalink":"/ChatBlog/dev/blog/tags/remote-workspace"}],"readingTime":6.6,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Hermes SSH Mode\uff1a\u8ba9\u6a21\u578b\u5b89\u5168\u5730\u8fdb\u5165\u8fdc\u7aef\u5de5\u4f5c\u533a","date":"2026-06-29T00:00:00.000Z","slug":"hermes-ssh-mode-model-controlled-remote-workspace","tags":["hermes","ssh","agent","feishu","remote-workspace"],"description":"\u89e3\u91ca Hermes SSH Mode \u7684\u673a\u5236\u3001\u7528\u6cd5\u3001\u5b89\u5168\u8fb9\u754c\uff0c\u4ee5\u53ca\u4e3a\u4ec0\u4e48\u6a21\u578b\u9700\u8981\u4e00\u4e2a\u53ef\u53d1\u73b0\u7684 ssh_mode \u5de5\u5177\u6765\u4e3b\u52a8\u8bf7\u6c42\u8fdb\u5165\u548c\u9000\u51fa\u8fdc\u7aef\u5de5\u4f5c\u533a\u3002"},"unlisted":false,"prevItem":{"title":"Hello World\uff1aChatBlog \u6846\u67b6\u80fd\u529b\u5c55\u793a","permalink":"/ChatBlog/dev/blog/hello-world-writing-public-notes-with-chatblog"}},"content":"Hermes SSH Mode \u7684\u6838\u5fc3\u76ee\u6807\uff0c\u662f\u8ba9\u540c\u4e00\u4e2a Agent \u4f1a\u8bdd\u53ef\u4ee5\u5728\u9700\u8981\u65f6\u628a terminal\u3001file\u3001code execution \u7b49\u4efb\u52a1\u6267\u884c\u9762\u5207\u5230\u8fdc\u7aef\u673a\u5668\uff0c\u540c\u65f6\u4fdd\u7559\u6e05\u6670\u7684\u6388\u6743\u8fb9\u754c\u548c\u4f1a\u8bdd\u9694\u79bb\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n:::tip \u4e00\u53e5\u8bdd\u7ed3\u8bba\\nSSH Mode \u4e0d\u53ea\u662f\u201c\u5e2e\u6a21\u578b\u8dd1\u4e00\u6761 ssh \u547d\u4ee4\u201d\uff0c\u800c\u662f\u628a\u5f53\u524d\u4f1a\u8bdd\u7684\u5de5\u5177\u6267\u884c\u9762\u5207\u5230\u8fdc\u7aef\uff1b\u6a21\u578b\u8981\u80fd\u81ea\u4e3b\u8fdb\u5165/\u9000\u51fa\uff0c\u5fc5\u987b\u80fd\u770b\u5230\u4e00\u4e2a\u660e\u786e\u3001\u5b89\u5168\u3001\u53d7\u6388\u6743\u7ea6\u675f\u7684 `ssh_mode` \u5de5\u5177\u3002\\n:::\\n\\n## \u4e3a\u4ec0\u4e48\u9700\u8981 SSH Mode\\n\\n\u666e\u901a SSH \u547d\u4ee4\u9002\u5408\u4eba\u7c7b\u4e34\u65f6\u767b\u5f55\u4e00\u53f0\u673a\u5668\uff0c\u4f46\u5bf9 Agent \u6765\u8bf4\u8fd8\u4e0d\u591f\u3002\\n\\nAgent \u7684\u5de5\u4f5c\u4e0d\u662f\u53ea\u6267\u884c\u4e00\u6761\u547d\u4ee4\u3002\u5b83\u4f1a\u8fde\u7eed\u8c03\u7528\uff1a\\n\\n- `terminal`\uff1a\u8fd0\u884c\u547d\u4ee4\u3001\u770b\u8fdb\u7a0b\u3001\u8dd1\u6d4b\u8bd5\uff1b\\n- `read_file` / `write_file` / `patch` / `search_files`\uff1a\u8bfb\u5199\u548c\u641c\u7d22\u9879\u76ee\u6587\u4ef6\uff1b\\n- `execute_code`\uff1a\u8fd0\u884c\u5c0f\u811a\u672c\u505a\u9a8c\u8bc1\u6216\u81ea\u52a8\u5316\u3002\\n\\n\u5982\u679c\u53ea\u6709\u4e00\u6761 `ssh user@host` \u547d\u4ee4\uff0c\u540e\u7eed file/code \u5de5\u5177\u5e76\u4e0d\u4f1a\u81ea\u52a8\u77e5\u9053\u201c\u6211\u73b0\u5728\u5e94\u8be5\u5728\u8fdc\u7aef\u201d\u3002Hermes SSH Mode \u89e3\u51b3\u7684\u662f\u8fd9\u4e2a\u95ee\u9898\uff1a**\u628a\u67d0\u4e2a\u4f1a\u8bdd\u8303\u56f4\u5185\u7684\u5de5\u5177 backend \u7edf\u4e00\u5207\u5230 SSH remote**\u3002\\n\\n## \u4e24\u79cd SSH backend\uff1a\u7cfb\u7edf\u7ea7\u4e0e\u4f1a\u8bdd\u7ea7\\n\\nHermes \u91cc\u53ef\u4ee5\u4ece\u4e24\u4e2a\u5c42\u9762\u7406\u89e3 SSH\uff1a\\n\\n| \u6a21\u5f0f | \u5f71\u54cd\u8303\u56f4 | \u9002\u5408\u573a\u666f |\\n| --- | --- | --- |\\n| \u7cfb\u7edf\u7ea7 SSH backend | \u6574\u4e2a Hermes \u9ed8\u8ba4 terminal backend | \u8fd9\u53f0 Hermes \u5b9e\u4f8b\u4e3b\u8981\u5c31\u662f\u5728\u8fdc\u7aef\u5de5\u4f5c |\\n| Section / Thread \u7ea7 SSH Mode | \u5f53\u524d\u804a\u5929 section \u6216\u98de\u4e66 Thread | \u4e34\u65f6\u628a\u4e00\u4e2a\u4efb\u52a1\u5207\u5230\u8fdc\u7aef\uff0c\u5176\u4ed6\u804a\u5929\u4ecd\u4fdd\u6301\u672c\u5730 |\\n\\n\u4e24\u8005\u5bf9\u6a21\u578b\u7684\u5de5\u5177\u4f53\u9a8c\u5e94\u8be5\u662f\u7b49\u4ef7\u7684\uff1a\u53ea\u8981\u5f53\u524d\u4e0a\u4e0b\u6587\u5df2\u7ecf\u5904\u4e8e SSH backend\uff0c`terminal`\u3001\u6587\u4ef6\u5de5\u5177\u3001`execute_code` \u5c31\u5e94\u8be5\u90fd\u6253\u5230\u540c\u4e00\u4e2a\u8fdc\u7aef\u73af\u5883\u3002\\n\\n\u5dee\u522b\u5728\u4e8e\u8303\u56f4\uff1a\u7cfb\u7edf\u7ea7\u662f\u5168\u5c40\u9ed8\u8ba4\uff0c\u4f1a\u8bdd\u7ea7\u662f\u5c40\u90e8\u7ed1\u5b9a\u3002\\n\\n## \u5728\u98de\u4e66\u91cc\u63a8\u8350\u7684\u4f7f\u7528\u65b9\u5f0f\\n\\nHermes \u5728 Feishu / Lark \u91cc\u4f7f\u7528 SSH Mode \u65f6\uff0c\u63a8\u8350\u628a\u8fdc\u7aef\u5de5\u4f5c\u653e\u8fdb Thread\uff0c\u800c\u4e0d\u662f\u6c61\u67d3\u7236\u4f1a\u8bdd\u3002\\n\\n| \u76ee\u6807 | \u547d\u4ee4 | \u8bf4\u660e |\\n| --- | --- | --- |\\n| \u5728\u7236\u4f1a\u8bdd\u8fdb\u5165\u8fdc\u7aef | `/ssh use <alias>` | \u9ed8\u8ba4\u521b\u5efa\u4e00\u4e2a Feishu Thread\uff0c\u5e76\u628a SSH \u7ed1\u5b9a\u5230\u8fd9\u4e2a Thread |\\n| \u5728\u5df2\u6709 Thread \u5207\u6362\u76ee\u6807 | `/ssh use <alias>` | \u53ea\u5f71\u54cd\u5f53\u524d Thread / section |\\n| \u67e5\u770b\u5f53\u524d\u72b6\u6001 | `/ssh status` | \u67e5\u770b\u662f\u5426\u7ed1\u5b9a SSH\u3001\u7ed1\u5b9a\u5230\u54ea\u4e2a target |\\n| \u56de\u5230\u672c\u5730 | `/ssh local` | \u63a8\u8350\u7684\u9000\u51fa\u65b9\u5f0f |\\n| \u517c\u5bb9\u65e7\u547d\u4ee4 | `/ssh off` | \u4fdd\u7559\u4e3a\u517c\u5bb9\u522b\u540d\uff0c\u4e0d\u4f5c\u4e3a\u4e3b\u8981\u6587\u6863\u5165\u53e3 |\\n\\n:::info Feishu Thread \u8fb9\u754c\\n\u7236\u4f1a\u8bdd\u91cc\u7684 `/ssh use <alias>` \u9ed8\u8ba4\u521b\u5efa Thread\uff0c\u662f\u4e3a\u4e86\u8ba9\u201c\u8fdc\u7aef\u4efb\u52a1\u4e0a\u4e0b\u6587\u201d\u6709\u4e00\u4e2a\u6e05\u6670\u8fb9\u754c\u3002\u7236\u4f1a\u8bdd\u7ee7\u7eed\u4fdd\u6301\u672c\u5730\uff0cThread \u5185\u540e\u7eed\u6d88\u606f\u624d\u8fdb\u5165\u8fdc\u7aef\u5de5\u4f5c\u6a21\u5f0f\u3002\\n:::\\n\\n## \u4e3a\u4ec0\u4e48\u6a21\u578b\u4e4b\u524d\u201c\u4e0d\u77e5\u9053\u600e\u4e48\u8fdb\u5165 SSH\u201d\\n\\n\u4e00\u4e2a\u91cd\u8981\u7ecf\u9a8c\u662f\uff1a\u6a21\u578b\u4e0d\u662f\u901a\u8fc7\u8bfb slash command \u5217\u8868\u6765\u81ea\u52a8\u83b7\u5f97\u6240\u6709\u80fd\u529b\u7684\u3002\u5b83\u4e3b\u8981\u4f9d\u8d56\u5f53\u524d\u8bf7\u6c42\u91cc\u66b4\u9732\u7ed9\u5b83\u7684\u5de5\u5177 schema\u3002\\n\\n\u5982\u679c `ssh_mode` \u5de5\u5177\u6ca1\u6709\u51fa\u73b0\u5728\u6a21\u578b\u53ef\u89c1\u7684\u5de5\u5177\u96c6\u4e2d\uff0c\u5373\u4f7f\u7cfb\u7edf\u5185\u90e8\u5df2\u7ecf\u652f\u6301 `/ssh use`\uff0c\u6a21\u578b\u4e5f\u5f88\u96be\u4e3b\u52a8\u53d1\u73b0\uff1a\\n\\n- \u5f53\u524d\u662f\u5426\u5df2\u7ecf\u5728 SSH\uff1f\\n- \u6709\u54ea\u4e9b SSH target\uff1f\\n- \u5982\u4f55\u8bf7\u6c42\u8fdb\u5165\uff1f\\n- \u5982\u4f55\u8bf7\u6c42\u9000\u51fa\uff1f\\n- \u4ec0\u4e48\u65f6\u5019\u9700\u8981\u7528\u6237\u6388\u6743\uff1f\\n\\n\u8fd9\u7c7b\u80fd\u529b\u9700\u8981\u4e00\u4e2a\u6a21\u578b\u53ef\u89c1\u7684 affordance\u3002\\n\\n```mermaid\\nflowchart LR\\n  U[\u7528\u6237\u610f\u56fe\uff1a\u53bb\u8fdc\u7aef\u5de5\u4f5c] --\x3e M[\u6a21\u578b]\\n  M --\x3e S{\u662f\u5426\u770b\u5f97\u5230 ssh_mode \u5de5\u5177\uff1f}\\n  S --\x3e|\u770b\u4e0d\u5230| X[\u53ea\u80fd\u731c\u6d4b/\u63d0\u793a\u7528\u6237\u624b\u52a8\u64cd\u4f5c]\\n  S --\x3e|\u770b\u5f97\u5230| A[ssh_mode.status / list_targets]\\n  A --\x3e B{\u662f\u5426\u6709 yolo \u6388\u6743\uff1f}\\n  B --\x3e|\u6ca1\u6709| C[\u8fd4\u56de approval_required\uff0c\u63d0\u793a\u7528\u6237\u6388\u6743\u6216\u624b\u52a8 /ssh use]\\n  B --\x3e|\u6709| D[request_use \u8fdb\u5165 SSH Mode]\\n  D --\x3e E[terminal / file / code \u5de5\u5177\u8d70\u8fdc\u7aef]\\n  E --\x3e F[request_local \u6216 /ssh local \u56de\u5230\u672c\u5730]\\n```\\n\\n\u56e0\u6b64\uff0cSSH Mode \u9700\u8981\u540c\u65f6\u6709\u4e24\u5c42\u5165\u53e3\uff1a\\n\\n1. **\u7528\u6237\u5165\u53e3**\uff1a`/ssh use`\u3001`/ssh local`\u3001`/ssh status`\uff1b\\n2. **\u6a21\u578b\u5165\u53e3**\uff1a`ssh_mode.status`\u3001`ssh_mode.list_targets`\u3001`ssh_mode.request_use`\u3001`ssh_mode.request_local`\u3002\\n\\n## \u6a21\u578b\u81ea\u4e3b\u5207\u6362\u5fc5\u987b\u6709\u6388\u6743\u8fb9\u754c\\n\\n\u8ba9\u6a21\u578b\u201c\u80fd\u8bf7\u6c42\u8fdb\u5165 SSH\u201d\uff0c\u4e0d\u7b49\u4e8e\u8ba9\u6a21\u578b\u968f\u4fbf\u5207\u673a\u5668\u3002\\n\\n\u4e00\u4e2a\u5b89\u5168\u7684\u6a21\u578b\u4fa7\u6d41\u7a0b\u5e94\u8be5\u662f\uff1a\\n\\n| \u60c5\u51b5 | \u884c\u4e3a |\\n| --- | --- |\\n| \u5f53\u524d section \u6ca1\u6709\u6388\u6743 | `request_use` \u8fd4\u56de\u9700\u8981\u6388\u6743 |\\n| \u7528\u6237\u8fd0\u884c `/ssh yolo on <alias>` | \u6a21\u578b\u53ef\u5728\u5f53\u524d section \u8bf7\u6c42\u8fdb\u5165\u8be5 alias |\\n| \u7528\u6237\u8fd0\u884c `/ssh yolo on all` | \u6a21\u578b\u53ef\u5728\u5f53\u524d section \u8bf7\u6c42\u8fdb\u5165\u4efb\u610f\u5df2\u914d\u7f6e target |\\n| \u7528\u6237\u7528 `/ssh use` \u624b\u52a8\u521b\u5efa sticky binding | \u6a21\u578b\u4e0d\u5e94\u64c5\u81ea\u6e05\u6389\u5b83 |\\n| \u6a21\u578b\u521b\u5efa\u7684\u4e34\u65f6 binding | \u6a21\u578b\u53ef\u7528 `request_local` \u6e05\u7406 |\\n\\n:::warning \u5b89\u5168\u8fb9\u754c\\n`/ssh yolo on <alias>` \u5e94\u8be5\u662f section-scoped \u6388\u6743\uff0c\u800c\u4e0d\u662f\u5168\u5c40\u6c38\u4e45\u6388\u6743\u3002\u5b83\u8ba9\u6a21\u578b\u5728\u5f53\u524d\u4efb\u52a1\u4e0a\u4e0b\u6587\u91cc\u66f4\u81ea\u4e3b\uff0c\u4f46\u4ecd\u7136\u628a\u6743\u9650\u9650\u5236\u5728\u7528\u6237\u660e\u786e\u6253\u5f00\u7684\u8303\u56f4\u5185\u3002\\n:::\\n\\n## SSH Mode \u5f71\u54cd\u4ec0\u4e48\uff0c\u4e0d\u5f71\u54cd\u4ec0\u4e48\\n\\n\u6700\u5bb9\u6613\u6df7\u6dc6\u7684\u662f\u201c\u4efb\u52a1\u6267\u884c\u9762\u201d\u548c\u201cHermes \u63a7\u5236\u9762\u201d\u3002\\n\\nSSH Mode \u5f71\u54cd\u7684\u662f\u4efb\u52a1\u6267\u884c\u9762\uff1a\\n\\n- `terminal`\\n- `read_file` / `write_file` / `patch` / `search_files`\\n- `execute_code`\\n\\n\u8fd9\u4e9b\u5de5\u5177\u5728\u5f53\u524d section \u8fdb\u5165 SSH \u540e\uff0c\u5e94\u5f53\u50cf\u5728\u8fdc\u7aef\u5de5\u4f5c\u4e00\u6837\u3002\\n\\n\u4f46 Hermes \u81ea\u5df1\u7684\u63a7\u5236\u9762\u4ecd\u7136\u5c5e\u4e8e\u672c\u5730 Hermes \u8fdb\u7a0b\u548c\u672c\u5730 profile\uff1a\\n\\n- `skill_view` / `skill_manage`\\n- memory\\n- cron jobs\\n- session database\\n- gateway \u72b6\u6001\\n- profile config\\n\\n\u8fd9\u610f\u5473\u7740\uff1a\u5982\u679c\u6a21\u578b\u5b8c\u6210\u4e00\u6b21\u8fdc\u7aef\u4efb\u52a1\u540e\uff0c\u8981\u66f4\u65b0\u81ea\u5df1\u7684 skill\uff0c\u6b63\u786e\u65b9\u5f0f\u662f\u8c03\u7528 `skill_manage`\uff0c\u5199\u5165\u672c\u5730 Hermes profile \u7684 skills\uff1b\u4e0d\u8981\u901a\u8fc7\u8fdc\u7aef file/terminal \u53bb\u6539\u8fdc\u7aef\u673a\u5668\u4e0a\u7684 `~/.hermes/skills`\uff0c\u9664\u975e\u76ee\u6807\u660e\u786e\u5c31\u662f\u7ef4\u62a4\u8fdc\u7aef\u90a3\u5957 Hermes \u5b89\u88c5\u3002\\n\\n```mermaid\\nflowchart TB\\n  subgraph Local[\u672c\u5730 Hermes \u8fdb\u7a0b / profile]\\n    G[Gateway / Feishu session]\\n    K[skill_manage / memory / cron / session DB]\\n    O[SSH binding registry]\\n  end\\n\\n  subgraph Remote[SSH \u8fdc\u7aef\u673a\u5668]\\n    T[terminal]\\n    F[file tools]\\n    C[execute_code]\\n  end\\n\\n  G --\x3e O\\n  O --\x3e T\\n  O --\x3e F\\n  O --\x3e C\\n  G --\x3e K\\n```\\n\\n## \u4e00\u4e2a\u63a8\u8350\u5de5\u4f5c\u6d41\\n\\n\u4e0b\u9762\u662f\u4e00\u4e2a\u5178\u578b\u7684 Feishu Thread \u5de5\u4f5c\u6d41\uff1a\\n\\n1. \u7528\u6237\u5728\u7236\u4f1a\u8bdd\u8bf4\uff1a\u8fd9\u4e2a\u4efb\u52a1\u53bb\u8fdc\u7aef\u505a\u3002\\n2. \u7528\u6237\u8fd0\u884c `/ssh use <alias>`\u3002\\n3. Hermes \u521b\u5efa\u4e00\u4e2a Thread\uff0c\u5e76\u628a\u8be5 Thread \u7ed1\u5b9a\u5230 SSH target\u3002\\n4. Thread \u4e2d\u7684\u540e\u7eed\u4efb\u52a1\uff0c`terminal` / file / code \u5de5\u5177\u90fd\u8d70\u8fdc\u7aef\u3002\\n5. \u5982\u679c\u5e0c\u671b\u6a21\u578b\u540e\u7eed\u80fd\u81ea\u5df1\u5207\u5165\u540c\u4e00 target\uff0c\u7528\u6237\u8fd0\u884c `/ssh yolo on <alias>`\u3002\\n6. \u4efb\u52a1\u5b8c\u6210\u540e\uff0c\u7528\u6237\u8fd0\u884c `/ssh local`\uff0c\u628a\u8be5 Thread \u56de\u5230\u672c\u5730 backend\u3002\\n\\n\u5982\u679c\u7528\u6237\u53ea\u60f3\u8ba9\u6a21\u578b\u201c\u5efa\u8bae\u8fdb\u5165\u201d\uff0c\u800c\u4e0d\u662f\u5141\u8bb8\u5b83\u81ea\u4e3b\u5207\u6362\uff0c\u5c31\u4e0d\u9700\u8981\u5f00 yolo\uff1a\u6a21\u578b\u770b\u5230\u7f3a\u5c11\u6388\u6743\u540e\uff0c\u5e94\u63d0\u793a\u7528\u6237\u624b\u52a8\u8fd0\u884c `/ssh use <alias>`\u3002\\n\\n## \u8bbe\u8ba1\u4e0a\u7684\u5173\u952e\u70b9\\n\\n\u8fd9\u6b21 SSH Mode \u7684\u7ecf\u9a8c\u53ef\u4ee5\u603b\u7ed3\u4e3a\u51e0\u6761\u901a\u7528 Agent \u8bbe\u8ba1\u539f\u5219\uff1a\\n\\n1. **Slash command \u662f\u7528\u6237 affordance\uff0c\u4e0d\u662f\u6a21\u578b affordance\u3002**  \u6a21\u578b\u8981\u81ea\u4e3b\u4f7f\u7528\u67d0\u80fd\u529b\uff0c\u9700\u8981\u5de5\u5177 schema \u6216\u7b49\u4ef7\u7684\u6a21\u578b\u53ef\u89c1\u5165\u53e3\u3002\\n2. **\u8fdc\u7aef backend \u8981\u8986\u76d6\u6574\u5957\u4efb\u52a1\u6267\u884c\u5de5\u5177\u3002**  \u53ea\u5207 terminal \u4e0d\u591f\uff0cfile/code \u5de5\u5177\u4e5f\u8981\u547d\u4e2d\u540c\u4e00\u4e2a backend\u3002\\n3. **Thread / section \u662f\u5929\u7136\u7684\u9694\u79bb\u8fb9\u754c\u3002**  \u5c24\u5176\u5728 IM \u573a\u666f\uff0c\u4e0d\u8981\u8ba9\u7236\u4f1a\u8bdd\u88ab\u4e34\u65f6\u8fdc\u7aef\u4efb\u52a1\u6c61\u67d3\u3002\\n4. **\u63a7\u5236\u9762\u4e0d\u8981\u88ab\u8fdc\u7aef backend \u610f\u5916\u52ab\u6301\u3002**  skills\u3001memory\u3001cron\u3001gateway \u7b49\u5c5e\u4e8e Hermes \u672c\u5730 profile\u3002\\n5. **\u81ea\u4e3b\u6027\u5fc5\u987b\u914d\u6388\u6743\u3002**  yolo grant \u5e94\u8be5\u662f\u663e\u5f0f\u3001\u5c40\u90e8\u3001\u53ef\u64a4\u9500\u7684\u3002\\n\\n## \u9002\u5408\u6c89\u6dc0\u6210 Skill \u7684\u5185\u5bb9\\n\\n\u535a\u5ba2\u9002\u5408\u89e3\u91ca\u6982\u5ff5\u548c\u8bbe\u8ba1\uff1bSkill \u9002\u5408\u8ba9\u6a21\u578b\u91cd\u590d\u6267\u884c\u6d41\u7a0b\u3002\\n\\nSSH Mode \u7684\u64cd\u4f5c Skill \u5e94\u8be5\u8bb0\u5f55\uff1a\\n\\n- \u5982\u4f55\u67e5\u770b `/ssh list` / `/ssh status`\uff1b\\n- \u5982\u4f55\u9a8c\u8bc1 target \u5143\u6570\u636e\u800c\u4e0d\u6cc4\u9732\u79c1\u94a5\u8def\u5f84\uff1b\\n- \u5982\u4f55\u4ece\u7236\u4f1a\u8bdd\u8fdb\u5165 Thread\uff1b\\n- \u5982\u4f55\u6388\u6743\u6a21\u578b\u81ea\u4e3b\u8bf7\u6c42\u8fdb\u5165\uff1b\\n- \u5982\u4f55\u9000\u51fa\u5230 local\uff1b\\n- \u5982\u4f55\u9a8c\u8bc1 terminal/file/code \u662f\u5426\u771f\u7684\u8d70\u8fdc\u7aef\uff1b\\n- \u54ea\u4e9b\u63a7\u5236\u9762\u4ecd\u7136\u662f\u672c\u5730\u3002\\n\\n\u8fd9\u7c7b\u5185\u5bb9\u4e00\u65e6\u7a33\u5b9a\uff0c\u5c31\u53ef\u4ee5\u6210\u4e3a\u6a21\u578b\u6bcf\u6b21\u5904\u7406 SSH Mode \u4efb\u52a1\u524d\u52a0\u8f7d\u7684\u64cd\u4f5c\u624b\u518c\u3002\\n\\n## \u7ed3\u8bed\\n\\nHermes SSH Mode \u7684\u4ef7\u503c\u4e0d\u53ea\u662f\u201c\u80fd\u8fde\u8fdc\u7aef\u201d\uff0c\u800c\u662f\u628a\u8fdc\u7aef\u6267\u884c\u3001\u4f1a\u8bdd\u9694\u79bb\u3001\u6a21\u578b\u53ef\u53d1\u73b0\u80fd\u529b\u548c\u7528\u6237\u6388\u6743\u653e\u8fdb\u540c\u4e00\u4e2a\u95ed\u73af\u91cc\u3002\\n\\n\u5f53\u8fd9\u4e2a\u95ed\u73af\u6210\u7acb\u540e\uff0c\u7528\u6237\u53ef\u4ee5\u7528 `/ssh use` \u660e\u786e\u5207\u6362\u4efb\u52a1\u4e0a\u4e0b\u6587\uff0c\u6a21\u578b\u4e5f\u53ef\u4ee5\u5728\u5f97\u5230\u6388\u6743\u540e\u4e3b\u52a8\u8bf7\u6c42\u8fdb\u5165\u6216\u9000\u51fa\u8fdc\u7aef\u73af\u5883\uff1b\u800c Hermes \u81ea\u5df1\u7684 skills\u3001memory\u3001profile \u4ecd\u7136\u4fdd\u6301\u5728\u672c\u5730\u63a7\u5236\u9762\u4e2d\uff0c\u4e0d\u4f1a\u56e0\u4e3a\u4e00\u6b21\u8fdc\u7aef\u4efb\u52a1\u800c\u6df7\u4e71\u3002"}]}}')}}]);